insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',1,'Língua Portuguesa',null,'Em todas as opções abaixo há uma frase, da qual foi retirada uma informação implícita (uma inferência). Assinale a opção em que a inferência apontada está adequada à frase.','{"A": "Quando se é velho, é preciso ser mais ativo do que quando jovem / os velhos trabalham mais que os jovens, por isso precisam de energia.", "B": "Uma criança mimada nunca ama sua mãe / é indispensável saber educar os filhos.", "C": "Nunca faças hoje o que podes deixar para amanhã / a pressa é amiga da perfeição.", "D": "Em toda iniciativa, pensa bem aonde queres chegar / em toda atividade, a disciplina financeira é indispensável.", "E": "Morrer gloriosamente é melhor do que salvar-se / a disciplina militar ajuda bastante na trajetória da vida."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',2,'Língua Portuguesa',null,'Observe o texto a seguir. “Dvorak aproximou-se da entrada da caverna e procurou observar o seu interior. Havia alguns restos de fogueiras e ossos de animais espalhados. Nas paredes, alguns desenhos ininteligíveis, em cores pálidas. O teto mostrava alguns buracos por onde penetrava a luz do sol. Dvorak aprofundou-se na gruta e notou que ela era muito mais funda do que aparentava. Certamente o grupo que conduzia poderia proteger-se ali, já que havia uma só entrada e algumas saídas poderiam ser arranjadas”. Sobre os diferentes gêneros textuais presentes nesse segmento, é correto afirmar que','{"A": "os segmentos do texto mostram estruturação narrativa, com sua básica evolução cronológica.", "B": "o texto é integralmente descritivo, tendo por objeto os aspectos visuais do interior da caverna.", "C": "o texto, após um início narrativo, desvia para a estruturação descritiva, terminando com uma reflexão do personagem.", "D": "o texto, de caráter dissertativo-expositivo, tenta mostrar as dificuldades de encontrar-se um lugar seguro para morar, na época pré-histórica.", "E": "o segmento final do texto mostra que sua finalidade é argumentativa."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',3,'Língua Portuguesa',null,'Assinale a opção que exemplifica um gênero textual diferente dos demais.','{"A": "A ciência comete suicídio quando adota um credo.", "B": "Não é possível que exista uma moral científica; mas também não é possível que haja uma ciência imoral.", "C": "Conhecer é um ato. A ciência pertence, portanto, ao âmbito da moral.", "D": "Não devemos acreditar em tudo que nos contam.", "E": "Não há nenhum mal no átomo, apenas na alma dos homens."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',4,'Língua Portuguesa',null,'Há frases interrogativas que são na verdade afirmações, pois a resposta já está contida implicitamente na pergunta, como no seguinte caso:','{"A": "Onde você acha que eu moro?", "B": "Pode-me mostrar tua carteira, por favor?", "C": "Gostaria de comer sobremesa?", "D": "Quem pode dizer que dessa água eu não beberei?", "E": "Onde está o meu celular?"}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',5,'Língua Portuguesa',null,'Assinale a frase em que a preposição para tem valor semântico diferente do das demais frases.','{"A": "Eu gosto do trabalho. Ele me fascina. Posso sentar e olhar para ele por horas.", "B": "Os turistas caminharam para a catedral da cidade, famosa por suas pinturas.", "C": "Para o ministro, a luta contra as injustiças sociais deve ser o principal do programa presidencial.", "D": "A solução para resolver os problemas da pesquisa era ir para a biblioteca.", "E": "Um casal deve caminhar sempre para a mesma meta."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',6,'Língua Portuguesa',null,'Observe o início de uma descrição, em que alguns artigos estão destacados. “Um casal dirigia-se a um restaurante do centro da cidade para comemorar 20 anos de casados; o restaurante estava repleto, mas havia ainda algumas mesas disponíveis; logo que se sentaram numa delas, um garçom aproximou-se e entregou-lhes o cardápio”. Sobre um desses artigos, assinale a afirmativa correta.','{"A": "“Um casal” mostra o artigo indefinido para indicar nenhuma importância narrativa.", "B": "o termo “o restaurante” mostra o artigo definido por já haver sido citado anteriormente.", "C": "o elemento “um restaurante” mostra o artigo indefinido para mostrar que se trata de um restaurante qualquer, sem sofisticação.", "D": "“um garçom” mostra um emprego inadequado do artigo indefinido.", "E": "“o cardápio” traz um artigo definido por ser um elemento inesperado na situação narrada."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',7,'Língua Portuguesa',null,'Assinale a frase que é expressa sem qualquer redundância, ou seja, emprego desnecessário de palavras.','{"A": "Existe um só sucesso: ser capaz de viver a sua vida do seu próprio jeito.", "B": "A loja fora montada com esforço e sua primeira inauguração se daria brevemente.", "C": "Entre todas as nações foram os gregos aqueles que de forma mais bela sonharam o sonho da vida.", "D": "Quem é tão firme de caráter que não pode ser seduzido?", "E": "Os caçadores, em função do perigo, tinham conseguido um abrigo protegido contra as feras."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',8,'Língua Portuguesa',null,'Assinale a frase cujo tema é a própria linguagem.','{"A": "Uma casa é feita de tijolo e pedra. Um lar é feito apenas de amor.", "B": "O destino normal das novas verdades é começar como heresias e terminar como superstições.", "C": "Se um homem não descobriu nada pelo que morreria, não está pronto para viver.", "D": "Tantas cabeças, quantas sentenças: cada um tem o seu modo de ver.", "E": "O medo segue o crime e é seu castigo."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',9,'Língua Portuguesa',null,'O verbo ficar pode ser empregado como verbo de ligação, com o sentido de “mudança de estado”, equivalente a “tornar-se”. Assinale a frase que serve de exemplo para esse emprego.','{"A": "Nossos corpos são onde nós ficamos, nossos espíritos são o que nós somos.", "B": "Os homens não podem ficar parados no mesmo lugar.", "C": "Onde fica o bairro da Prainha nesta cidade?", "D": "Os livros mais caros ficam nas prateleiras mais altas.", "E": "A justiça pode ficar cega, mas tem dispositivos de escuta muito sofisticados."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',10,'Língua Portuguesa',null,'Assinale a frase em que houve troca indevida entre se não / senão.','{"A": "O único senão da prova era a presença de textos muito longos.", "B": "Só ocorrerá a prova de ciclismo se não chover.", "C": "Fará a prova senão ficará arrependido.", "D": "Comprará um carro novo se não tiver problemas econômicos.", "E": "Ninguém, se não ela, para fazer esse trabalho."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',11,'Língua Portuguesa',null,'Todas as frases abaixo são compostas de dois períodos. A ligação lógica entre eles que está corretamente identificada, é:','{"A": "Faz parte da natureza dos mortais pisar ainda mais em quem já caiu. / os dois períodos estão em comparação.", "B": "Quando se tem tudo para temer, não se deve temer nada. / o segundo período é a causa do primeiro.", "C": "Eu não podia esperar pelo sucesso. Assim eu fui em frente sem ele. / o segundo período é uma conclusão do primeiro.", "D": "A vitória tem mil pais, mas a derrota é órfã. / o segundo período é cronologicamente posterior ao primeiro.", "E": "É melhor reinar no inferno do que servir no céu. / os períodos mostram uma relação de alternância."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',12,'Língua Portuguesa',null,'Assinale a frase em que houve troca indevida entre os parônimos colocados entre parênteses.','{"A": "Durante a conversa, ele não pôde deixar de fazer alusão à sua vida difícil (alusão / ilusão).", "B": "Ele evocou o heroísmo de seus comandados (evocou / invocou).", "C": "Diante daquela proposta inepta ele se limitou a bocejar (inepta / inapta).", "D": "A família perpetuava a memória do general, levando flores ao túmulo (perpetuava / perpetrava).", "E": "Pensando no futuro, o presidente se perdia em toda espécie de conjecturas (conjecturas / conjunturas)."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',13,'Língua Portuguesa',null,'Assinale a frase em que a expressão “é que” não mostra valor enfático, fazendo parte da estrutura sintática da frase.','{"A": "É o uniforme que faz esquecer aquele que o veste.", "B": "O hábito é que torna suportáveis até as coisas assustadoras.", "C": "A resposta é que todos devem colaborar.", "D": "A leitura é que nos torna mais cultos.", "E": "Não sabemos quando é que custa a vida."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',14,'Língua Portuguesa',null,'“O modo de se vestir é uma preocupação ridícula. Mas é muito ridículo para um homem não estar bem-vestido”. Sobre os componentes e o sentido desse pensamento de um estadista inglês, assinale a afirmação inadequada.','{"A": "O segmento “O modo de se vestir” mostra uma forma impessoal.", "B": "O segundo período funciona como argumento a favor do anterior.", "C": "Há uma contradição clara entre os dois períodos da frase.", "D": "O primeiro período do texto contém valor concessivo.", "E": "O segmento “não estar bem-vestido” equivale a “estar malvestido”."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',15,'Língua Portuguesa',null,'Assinale a frase em que a substituição do adjetivo sublinhado por uma oração adjetiva de valor semântico equivalente foi feita de forma adequada.','{"A": "O estilo é um modo muito simples de dizer coisas complicadas / que se complicam.", "B": "Serviço de emergência disponível só com 24 horas de antecedência / que se mostra disposto.", "C": "Meu animal favorito é o bife / que me favorece.", "D": "Moda, afinal, são apenas epidemias induzidas / que se induzem.", "E": "O poder não satisfaz, é como a droga que sempre exige doses maiores / que são mais perigosas."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',16,'Língua Portuguesa',null,'O adjetivo pode ser substituído por algumas outras palavras ou estruturas de valor equivalente. Assinale a frase em que a adjetivação relacionada ao substantivo sublinhado é realizada por meio de uma oração desenvolvida.','{"A": "O homem que se vende recebe sempre mais do que vale.", "B": "Os lutadores determinados a vencer são adversários difíceis.", "C": "Não confie nas mulheres de mais de quarenta anos.", "D": "Os livros escritos no Romantismo são sentimentais.", "E": "As frutas alimentam o corpo e a alma."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',17,'Língua Portuguesa',null,'Nas frases a seguir foram feitas modificações de modo a mudar o adjetivo da primeira frase para substantivo na segunda. Assinale a opção em que essa modificação é inadequada.','{"A": "A afirmação categórica / a categorização da afirmação.", "B": "Uma frase prolixa / a prolixidade da frase.", "C": "Uma apresentação brilhante / o brilhantismo da apresentação.", "D": "A cor opaca / a opacidade da cor.", "E": "O céu escuro / a escuridão do céu."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',18,'Língua Portuguesa',null,'“Um asno será sempre um asno, mesmo se o cobrires de ouro”. A ideia central dessa frase é a de que','{"A": "os animais nunca deixarão de ser animais.", "B": "os seres menores costumam apresentar-se como maiores.", "C": "a riqueza não deve ser desperdiçada.", "D": "muda-se a aparência, mas não a essência.", "E": "homens e animais se equiparam."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',19,'Língua Portuguesa',null,'As frases a seguir são construídas com dois segmentos. Assinale aquela em que não há oposição entre eles.','{"A": "Nos mortos eu sempre lia alguma coisa nova / e nos vivos ouvia repetir mil vezes mil coisas velhas.", "B": "Chama-se perseverança quando é por uma boa causa / e obstinação quando é por uma ruim.", "C": "O poder desgosta / quem não o possui.", "D": "O segredo de todo poder consiste em saber / que os outros são mais covardes do que nós.", "E": "Deus fez a fêmea / e os costureiros fizeram a mulher."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',20,'Língua Portuguesa',null,'Observe o seguinte segmento textual, de autoria do célebre escritor francês Diderot: “Além do equador um homem não é inglês, holandês, francês, espanhol ou português. Ele se apega somente àqueles princípios e preconceitos de seu país de origem que justificam a sua conduta ou servem de desculpa para esta. Ele rasteja quando está fraco; ele é violento quando forte; ele tem pressa para adquirir, pressa para desfrutar, e é capaz de todo crime que o conduza mais rapidamente a seus objetivos. Ele é um tigre doméstico que retorna à selva; a sede de sangue toma conta dele outra vez. É assim que todos os europeus, cada um deles indistintamente, têm se mostrado nos países do Novo Mundo. Um delírio coletivo toma conta deles – a sede de ouro”. Todas as opções a seguir trazem informações explícitas ou implícitas contidas nesse texto. Assinale a opção que mostra uma informação explícita.','{"A": "quando viajam para o Novo Mundo, todos os europeus pretendem enriquecer.", "B": "os europeus, quando no Novo Mundo, voltam a um estágio anterior primitivo, não respeitando as leis.", "C": "os europeus, culturalmente falando, são superiores aos povos do Novo Mundo.", "D": "os europeus, no Novo Mundo, apesar de diferentes países, se igualam em seu procedimento primitivo e ilegal.", "E": "os europeus procedem de forma irracional quando, no Novo Mundo, pretendem adquirir riqueza. Informática"}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',21,'Informática',null,'O Word 2019 e o Excel 2019 salvam seus arquivos em determinados formatos por padrão. Assinale as extensões que correspondem aos formatos de arquivo padrão para o Word 2019 e o Excel 2019, respectivamente.','{"A": ".doc .xls", "B": ".docx .xlsx", "C": ".odt .ods", "D": ".xls .txt", "E": ".xlsl .docx"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',22,'Informática',null,'Um usuário do Windows em português tem instaladas e configuradas 3 impressoras, HP 3160, HP LaserJet Pro 400 e HP Deskjet Plus 6476, tendo definido a segunda delas como impressora padrão. Nesse cenário, e dado que há outras impressoras disponíveis, assinale a afirmativa correta.','{"A": "Somente será possível imprimir na impressora HP LaserJet Pro 400.", "B": "Para utilizar qualquer impressora que não a HP LaserJet Pro 400, o usuário deverá realizar o mesmo procedimento e alterar a impressora padrão.", "C": "Caso a impressora HP LaserJet Pro 400 seja removida, o usuário não conseguirá imprimir em outra impressora.", "D": "No envio de material para impressão, sem designação específica da impressora, a impressora HP LaserJet Pro 400 será selecionada automaticamente.", "E": "Para remover a impressora HP LaserJet Pro 400, o usuário deve, previamente, designar uma nova impressora padrão."}'::jsonb,'D',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',23,'Informática',null,'Considere o seguinte trecho de uma planilha MS Excel exibida no modo Mostrar Fórmulas (guia Fórmulas): A B C D 1 3 3 11 0 2 2 2 13 5 3 5 =MÉDIA(D1:D4) 15 =SOMA(A1:B2) 4 1 0 10 1 Dado que a coluna “C” foi selecionada e excluída completamente, assinale os valores exibidos nas células B3 e C3, respectivamente, depois dessa operação.','{"A": "10 e 4.", "B": "4 e 10.", "C": "4 e 15.", "D": "4 e 5.", "E": "5 e 4."}'::jsonb,'B',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',24,'Informática',null,'No Windows, há um conjunto de caracteres que não podem ser usados em nomes de pastas e arquivos. Faz parte dessa lista de caracteres inválidos o caractere','{"A": "-", "B": "$", "C": "(", "D": "*", "E": "_"}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',25,'Informática',null,'Avalie as afirmativas a seguir, a respeito do Pincel de Formatação (PF) do MS Word: I. Os tipos de fontes não são afetados pela aplicação do PF. II. Os tamanhos das fontes não são afetados pela aplicação do PF. III. O PF pode ser acionado pelo mouse, com um clique simples ou um clique duplo. Está correto o que se afirma em','{"A": "II e III, apenas.", "B": "I e II, apenas.", "C": "I, apenas.", "D": "II, apenas.", "E": "III, apenas. Legislação"}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',26,'Processo Legislativo',null,'Determinada Comissão da Assembleia Legislativa do Estado do Maranhão (ALEMA) terá de examinar uma proposição que veicula uma matéria em regime de prioridade. Assim, em regra, dita Comissão obedecerá ao seguinte prazo para exame dessa matéria:','{"A": "cinco dias.", "B": "oito dias.", "C": "dez dias.", "D": "quinze dias.", "E": "trinta dias."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',27,'Processo Legislativo',null,'A iniciativa popular de lei é um mecanismo singular de participação da sociedade civil nos rumos do governo. Por isso, é prevista também no Regimento Interno da Assembleia Legislativa do Estado do Maranhão (ALEMA), o qual veicula algumas regras para a tramitação de tais projetos de iniciativa popular. Acerca desse tema e à luz do referido Regimento Interno, avalie se as afirmativas a seguir são falsas (F) ou verdadeiras (V): ( ) Será lícito a entidade da sociedade civil patrocinar a apresentação de projeto de lei de iniciativa popular, responsabilizando-se inclusive pela coleta das assinaturas. ( ) Projeto de lei de iniciativa popular pode versar sobre o plano de carreiras do Ministério Público Estadual. ( ) O projeto de lei de iniciativa popular deve ser subscrito por, no mínimo, um por cento do eleitorado estadual, distribuído por pelo menos dezoito por cento dos municípios, com não menos de três décimos por cento dos eleitores de cada um deles. As afirmativas são, respectivamente,','{"A": "V – V – V.", "B": "V – V – F.", "C": "V – F – V.", "D": "F – V – F.", "E": "F – F – F."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',28,'Processo Legislativo',null,'A apreciação de Proposta de Emenda à Constituição do Estado do Maranhão está entre as atividades mais relevantes da Assembleia Legislativa do Estado do Maranhão (ALEMA) no exercício de seu poder constituinte decorrente. Acerca dessa competência no Regimento Interno da ALEMA, assinale a afirmativa correta.','{"A": "A proposta de Emenda à Constituição será submetida a três turnos de discussão e votação.", "B": "Será aprovada a proposta que obtiver, em todos os turnos de votação, o voto favorável da maioria absoluta dos membros da ALEMA, em votação nominal.", "C": "A matéria constante de proposta de Emenda à Constituição rejeitada ou havida por prejudicada pode ser objeto de nova proposta na mesma sessão legislativa se subscrita por maioria absoluta dos membros da ALEMA.", "D": "A Emenda à Constituição será promulgada pelo Presidente da ALEMA com o respectivo número de ordem e dela enviada cópia ao Governador do Estado e ao Presidente do Tribunal de Justiça.", "E": "A ALEMA apreciará proposta de Emenda à Constituição se for apresentada por mais da metade das Câmaras Municipais do Estado com a manifestação de cada uma delas, pela maioria relativa de seus membros."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',29,'Processo Legislativo',null,'Em determinada sessão plenária da Assembleia Legislativa do Estado do Maranhão (ALEMA), estavam presentes, ocupando as bancadas, deputados estaduais, convidados do Presidente, ex- parlamentares e funcionários da ALEMA cujas funções estavam diretamente ligadas à sessão plenária. Um dos deputados estaduais inscrito como orador solicitou ao Presidente para falar sentado e de sua bancada. Acerca dessa sessão, de acordo com o Regimento Interno da ALEMA, é correto afirmar que','{"A": "convidados do Presidente podem participar de sessão da ALEMA ocupando as bancadas.", "B": "funcionários da ALEMA que estejam a exercer funções diretamente ligadas à sessão podem permanecer no Plenário e, havendo vagas, inclusive ocupar bancadas.", "C": "em razão de já terem ocupado o cargo público no passado, ex- parlamentares possuem a prerrogativa regimental de, estando presentes às sessões, ocuparem bancadas que estejam vagas.", "D": "o orador deverá falar obrigatoriamente da tribuna, e não de sua bancada.", "E": "o orador deverá falar obrigatoriamente de pé, e não sentado."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',30,'Processo Legislativo',null,'José, servidor público da Assembleia Legislativa do Estado do Maranhão não reincidente em falta funcional, fez uma crítica ao Governador do Estado do Maranhão, com uso de palavras depreciativas, em determinado despacho em processo administrativo que estava sob sua condução. Sobre a conduta de José, à luz do Estatuto dos Servidores Públicos Civis do Estado do Maranhão, é correto afirmar que','{"A": "é lícito a José criticar autoridade pública em tal despacho, ainda que se utilize de palavras depreciativas, desde que seus atos não constituam crimes contra a honra.", "B": "José cometeu falta administrativa, sendo passível de punição com suspensão por até 15 (quinze) dias.", "C": "José cometeu falta administrativa, sendo passível de punição com multa correspondente a até 5 (cinco) dias de sua remuneração.", "D": "José cometeu falta administrativa, sendo passível de punição com pena de advertência por escrito.", "E": "José, por não ser reincidente, embora tenha cometido falta administrativa, é passível de punição com pena de advertência de forma oral. Conhecimentos Específicos"}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',31,'Direito Constitucional',null,'Em uma gincana jurídica, os dois grupos envolvidos deveriam indicar, na perspectiva prevalecente no direito brasileiro, as características do poder constituinte originário. O grupo Alfa argumentava se tratar de um poder de direito, de caráter permanente, e ao qual não são oponíveis direitos adquiridos. O grupo Beta, por sua vez, ressaltava a característica da iniciabilidade e o seu caráter incondicionado na perspectiva formal, sendo-lhe possível constitucionalizar o direito pré- constitucional de natureza infraconstitucional. Os jurados, ao avaliarem os posicionamentos dos dois grupos, concluíram corretamente que','{"A": "os dois grupos estão totalmente certos.", "B": "os dois grupos estão parcialmente certos.", "C": "o grupo Alfa está parcialmente certo e o grupo Beta, totalmente certo.", "D": "o grupo Alfa está totalmente errado e o grupo Beta, totalmente certo.", "E": "o grupo Alfa está totalmente certo e o grupo Beta, parcialmente certo."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',32,'Direito Constitucional',null,'O Estado Alfa editou a Lei nº X, dispondo que os contratos de concessão em vigor, afetos à prestação do serviço local de gás canalizado, seriam prorrogados por dois anos. De acordo com a justificativa apresentada, foi esclarecido que o objetivo da prorrogação era o de viabilizar a realização de estudos destinados à alteração do modelo de exploração do serviço. À luz da sistemática constitucional vigente, é correto afirmar, em relação a essa narrativa, que a Lei nº X','{"A": "incursionou em temática afeta à competência legislativa municipal.", "B": "somente pode vir a ser apreciada pelo Supremo Tribunal Federal em sede de controle difuso de constitucionalidade.", "C": "somente pode ser objeto de arguição de descumprimento de preceito fundamental, por não se tratar de lei em sentido material.", "D": "não pode ser submetida ao controle concentrado de constitucionalidade perante o Supremo Tribunal Federal, por se tratar de lei de efeitos concretos.", "E": "pode ser objeto de ação direta de inconstitucionalidade, a ser ajuizada perante o Supremo Tribunal Federal, por se tratar de lei em sentido formal."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',33,'Direito Constitucional',null,'Determinada associação de Municípios, em uma assembleia ordinária, constatou que, na quase totalidade dos entes municipais que a integravam, foi editada uma lei cujo teor era rotineiramente reproduzido em cada um desses entes. Aqueles que ainda não tinham editado lei similar, estavam prestes a fazê- lo, já que o processo legislativo se encontrava em curso. Apesar de a constitucionalidade dessas leis ser defendida por muitos juristas, diversos juízes e tribunais estavam se negando a aplicá-las, sob o argumento de incompetência dos Municípios para legislar sobre a matéria. Isto ocorria apesar de o Supremo Tribunal Federal já ter reconhecido a inconstitucionalidade de leis editadas pela União e pelos Estados a respeito da matéria, ressaltando se tratar de competência municipal. Em razão desse debate, o Procurador-Geral do Município Alfa solicitou que sua assessoria analisasse a possibilidade de o Município requerer a edição de uma súmula vinculante sobre a matéria, pois, em determinada relação processual, caso fosse reconhecida a inconstitucionalidade de lei similar, seria grande o prejuízo que seria causado à edilidade. À luz da sistemática vigente, é correto afirmar que o objetivo alvitrado pelo Procurador-Geral do Município','{"A": "não é possível, pois a súmula vinculante não pode ter por objeto a discussão de direito municipal.", "B": "é possível, o que deve ser feito incidentalmente ao curso do processo em que o Município Alfa é parte.", "C": "não é possível, pois somente os legitimados à deflagração do controle concentrado de constitucionalidade podem fazê-lo, mas é cabível a reclamação.", "D": "não é possível, pois a súmula vinculante deve ser editada em caráter abstrato, baseada em decisões pretéritas, estando dissociada de uma controvérsia atual.", "E": "é possível, sendo a proposição encaminhada ao Supremo Tribunal Federal caso o juízo competente reconheça a relevância da controvérsia para a relação processual."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',34,'Direito Constitucional',null,'Um legitimado ingressou com ação direta de inconstitucionalidade contra a Lei nº X, do Estado Alfa, argumentando com a sua total incompatibilidade em relação à Constituição da República. Esse diploma normativo exigiu o preenchimento de certos requisitos, pela generalidade dos beneficiários, para a fruição de determinado benefício. Ao julgar o caso, o Supremo Tribunal Federal considerou que os requisitos previstos, apesar de serem compatíveis com a ordem constitucional, não poderiam ser exigidos de uma classe de beneficiários em potencial. Essa decisão teria eficácia contra todos e efeito vinculante em relação aos órgãos do Poder Judiciário e à Administração Pública federal, estadual e municipal. Considerando a técnica de decisão adotada, é correto afirmar que o Tribunal realizou uma','{"A": "declaração parcial de inconstitucionalidade sem redução de texto, que tem base legal.", "B": "interpretação conforme à Constituição, que tem base jurisprudencial, não legal.", "C": "restrição de sentido, com redução textual parcial, que tem base jurisprudencial e legal.", "D": "declaração de constitucionalidade parcial, com redução de sentido, que tem base legal.", "E": "declaração de nulidade parcial, com limitação de significantes, que tem base legal."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',35,'Direito Constitucional',null,'João, estudante de direito, tinha muitas dúvidas em relação à conhecida classificação das formas de governo oferecida por Aristóteles. Após ampla digressão teórica, o Professor explicou corretamente a João que o referido pensador','{"A": "distinguia as formas de governo normais das anormais, o que decorria de um critério ético, baseado no atendimento ao interesse geral.", "B": "situava as formas de governo nos referenciais de democracia, teocracia e clerocracia, conforme o seu fundamento fosse o povo, a nobreza ou o clero.", "C": "lastreava as formas de governo direcionadas ao bem comum em referenciais de base axiológica, explicitados nos valores de honra, moderação e virtude.", "D": "concebia o governo de maneira monolítica, lastreado na vontade popular, o que caracterizava a democracia, sendo plúrimo o seu modo de exercício.", "E": "concebia duas formas de governo, que expressavam a concepção de república própria dos antigos, sendo dividida em república aristocrática e república democrática."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',36,'Direito Constitucional',null,'Em razão de ampla mobilização popular, o Estado Alfa, com o objetivo de proteger as vítimas e as testemunhas de infrações penais, editou a Lei nº XX, a partir de projeto de lei de iniciativa parlamentar, estatuindo o sigilo no boletim de ocorrência e no inquérito policial no âmbito do referido ente federativo. Por entender que a Lei nº XX era flagrantemente prejudicial à sua atividade, a associação dos veículos de comunicação social solicitou que sua assessoria jurídica analisasse a compatibilidade desse diploma normativo com a ordem constitucional. A assessoria respondeu corretamente que a Lei nº XX é','{"A": "inconstitucional, por violar a liberdade de informação.", "B": "inconstitucional, pois está presente o vício de iniciativa.", "C": "constitucional, por se enquadrar no âmbito da competência legislativa residual dos Estados.", "D": "inconstitucional, por violar a competência privativa da União para legislar sobre processo penal.", "E": "constitucional, por se ajustar à competência concorrente entre a União e os Estados para legislar sobre matéria procedimental."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',37,'Direito Constitucional',null,'Com o objetivo de incentivar a solidariedade social e zelar pela saúde coletiva, o Estado Alfa editou a Lei nº XX, determinando que as sociedades empresárias que explorem o serviço de telefonia em seu território insiram, nas faturas de consumo, mensagens de incentivo à doação de sangue. Irresignado com o teor da Lei nº XX, o Partido Político Delta ingressou com ação direta de inconstitucionalidade perante o Supremo Tribunal Federal, argumentando a incompatibilidade entre esse diploma normativo e a Constituição da República. À luz dessa narrativa, é correto afirmar que o referido Tribunal deve julgar o pedido','{"A": "procedente, considerando a evidente afronta à livre iniciativa e ao princípio da proporcionalidade.", "B": "procedente, considerando que a União figura como poder concedente nos contratos de concessão do serviço de telefonia.", "C": "procedente, considerando que compete privativamente à União legislar sobre seguridade social em suas distintas vertentes.", "D": "improcedente, considerando que a matéria é de competência comum entre a União, os Estados, o Distrito Federal e os Municípios.", "E": "improcedente, considerando que os Estados possuem competência concorrente com a União para legislar sobre proteção à saúde."}'::jsonb,'E',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',38,'Direito Constitucional',null,'Em razão de um grande escândalo de corrupção envolvendo autoridades do alto escalão do Estado Alfa, houve um debate no qual foi suscitada a impossibilidade de ser iniciado o processo penal em detrimento do Governador do Estado Alfa sem prévia autorização da estrutura legislativa competente. Considerando os balizamentos estabelecidos pela sistemática constitucional, é correto afirmar que a referida autorização é','{"A": "desnecessária, salvo se houver previsão expressa na Constituição do Estado Alfa.", "B": "necessária, por força do princípio da simetria, ainda que essa exigência não esteja expressa na Constituição Estadual.", "C": "necessária, o que decorre de previsão constitucional expressa, enquanto emanação do princípio da separação dos poderes.", "D": "desnecessária, pois a Constituição da República não contempla regra que autorize a previsão dessa exigência em relação ao Governador do Estado.", "E": "desnecessária, pois não há nenhuma situação em que o início do processo criminal esteja condicionado à autorização de órgão estranho ao Poder Judiciário."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',39,'Direito Constitucional',null,'Ana nasceu em território turco, sendo filha de pai alemão e mãe francesa, os quais trabalhavam na embaixada brasileira localizada na Turquia. Após crescer estudando a cultura brasileira, pois recebia influência direta do emprego dos seus pais, e completar 18 anos, Ana decidiu que seguiria carreira política no Brasil. Ao decidir realizar esse sonho, consultou um advogado a respeito da sua nacionalidade, sendo-lhe corretamente informado que, à luz da ordem constitucional brasileira, ela é','{"A": "brasileira nata.", "B": "brasileira nata, desde que tenha sido registrada na embaixada brasileira da Turquia.", "C": "estrangeira, mas pode optar pela nacionalidade brasileira caso venha a residir no Brasil.", "D": "estrangeira, mas pode se naturalizar brasileira caso sejam preenchidos os requisitos previstos em lei ordinária.", "E": "estrangeira, mas pode se naturalizar brasileira, o que pressupõe o requisito indispensável de que resida quinze anos interruptos no Brasil e não tenha condenação penal."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',40,'Direito Constitucional',null,'João, marido de Maria, governadora do Estado Beta, almejava concorrer ao cargo eletivo de Deputado Estadual, no mesmo Estado, nas eleições a serem realizadas no ano seguinte. Para sua tristeza, Maria faleceu no ano da eleição. À luz da sistemática constitucional, é correto afirmar que João','{"A": "está inelegível para o cargo almejado, qualquer que seja o mês de falecimento de Maria.", "B": "está elegível para o cargo almejado, pois a ordem constitucional não alberga inelegibilidades reflexas, apenas inelegibilidades pessoais.", "C": "somente está inelegível para o cargo almejado caso Maria tenha falecido nos seis meses anteriores à eleição.", "D": "está inelegível para o cargo almejado, salvo se Maria, como Vice-Governadora, sucedeu o Governador no curso do mandato.", "E": "está elegível para o cargo almejado, independente do falecimento de Maria, considerando que almeja ocupar cargo no Poder Legislativo, não no Executivo."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',41,'Direito Constitucional',null,'Após amplo levantamento, a Secretaria de Patrimônio do Estado Alfa constatou a existência de uma larga faixa de terra, ao sul do seu território, que jamais recebera qualquer destinação pelo Poder Público ou integrara o patrimônio de um particular. Essa faixa de terra, ademais, era considerada indispensável, pelos biólogos, à preservação de um ecossistema próximo. Considerando as dificuldades de fluxo de caixa do Estado Alfa, a referida Secretaria sugeriu ao Governador do Estado a alienação dessa faixa de terra. É correto afirmar que a sugestão apresentada','{"A": "não pode ser acolhida por se tratar de terra pertencente à União.", "B": "não pode ser acolhida, por se tratar de terra pertencente aos Municípios.", "C": "pode ser acolhida, o que pressupõe prévia autorização da Assembleia Legislativa.", "D": "pode ser acolhida, o que decorre do poder de gestão do Chefe do Poder Executivo, salvo se a faixa de terra tiver sido declarada como área de preservação ambiental.", "E": "pode ser acolhida, o que decorre do poder de gestão do Chefe do Poder Executivo, salvo se a indispensabilidade à proteção ambiental tiver sido reconhecida em lei da União."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',42,'Direito Constitucional',null,'A Constituição do Estado Alfa, com o objetivo de ampliar os níveis de controle popular sobre as decisões políticas do Chefe do Poder Executivo, foi reformada e passou a dispor que todas as nomeações para secretarias de governo, no âmbito do Estado Alfa e dos Municípios situados em seu território, deveriam ser previamente aprovadas pelo Poder Legislativo, vale dizer, pela Assembleia Legislativa ou pela Câmara Municipal, conforme o caso. Ao tomar conhecimento da reforma promovida na Constituição Estadual, o Prefeito do Município Beta determinou que sua assessoria analisasse a compatibilidade da reforma com a Constituição da República, sendo-lhe corretamente informado que ela é','{"A": "constitucional, já que a Constituição Estadual é a sedes materiae para a disciplina do exercício do poder no âmbito estadual e municipal.", "B": "constitucional, já que a Constituição Estadual se limita a integrar a eficácia de norma programática já prevista na Constituição da República.", "C": "constitucional apenas em relação ao Estado Alfa, mas inconstitucional ao estender esse comando aos Municípios, isto por violar a sua autonomia.", "D": "inconstitucional, já que a Constituição da República limita a chancela, pelo Poder Legislativo, à aprovação dos ocupantes dos órgãos de cúpula da Administração Indireta.", "E": "inconstitucional, já que a reforma afronta a separação dos poderes ao estabelecer indevida ingerência do Poder Legislativo em atividade própria do Executivo."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',43,'Direito Constitucional',null,'Mariana, servidora pública ocupante de cargo de provimento efetivo no âmbito do Estado Alfa, que era organizado em carreira, subdividida em três classes, cada qual contando com cinco padrões, tomou ciência da recente aprovação da Lei estadual nº X, que determinava a aplicação da sistemática de subsídios aos servidores que se encontravam na situação dela. Em razão da edição da Lei estadual nº X, Mariana consultou o seu advogado a respeito da compatibilidade desse diploma normativo com a Constituição da República, sendo-lhe corretamente respondido que ele é','{"A": "constitucional, considerando que compete a cada ente federativo, no exercício de sua autonomia política, definir os cargos efetivos, eletivos ou em comissão, que serão alcançados pela sistemática de subsídios.", "B": "inconstitucional, pois os cargos suscetíveis de enquadramento na sistemática de subsídios estão elencados em numerus clausus em lei complementar federal, não sendo o caso do cargo ocupado por Mariana.", "C": "constitucional, pois a sistemática de subsídios pode ser estendida aos servidores em situação similar à de Mariana, sendo vedado o acréscimo de qualquer outro valor remuneratório a essa parcela única.", "D": "inconstitucional, pois a sistemática de subsídios somente pode ser aplicada ao membro de Poder, ao detentor de mandato eletivo, aos Ministros e aos Secretários.", "E": "constitucional, considerando que passou a ser cogente a aplicação da sistemática de subsídios à generalidade dos servidores públicos organizados em carreira."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',44,'Direito Constitucional',null,'Os servidores públicos do Estado Sigma realizaram uma grande mobilização visando a alterar a sistemática previdenciária que lhes era aplicável. O principal ponto de insatisfação consistia na sua atual vinculação ao regime geral de previdência social, o que era considerado muito desvantajoso, a começar pelo teto dos benefícios pagos nesse regime. Sensibilizado com a manifestação, e por considerar injusto o tratamento dispensado aos servidores, o Deputado Estadual João solicitou que sua assessoria analisasse a forma pela qual poderia ser instituído um regime próprio de previdência social (RPPS) no Estado Alfa, sendo-lhe corretamente informado que','{"A": "a instituição de RPPS exige a apresentação de projeto de lei de iniciativa do Chefe do Poder Executivo e pressupõe a demonstração de superávit no fluxo de receitas e despesas.", "B": "a instituição de RPPS pressupõe projeto de iniciativa do Chefe do Poder Executivo, que só pode ser apresentado, em razão de norma constitucional de transição, até o fim de 2023.", "C": "a instituição de RPPS pressupõe a edição de lei complementar estadual, que deve seguir os balizamentos estabelecidos pela lei nacional que trata da temática.", "D": "a instituição de RPPS somente pode ser realizada a partir de reforma da Constituição Estadual, observado o poder de iniciativa nela estabelecido.", "E": "é vedada a instituição de RPPS."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',45,'Direito Constitucional',null,'Joana, oficial médica da Polícia Militar do Estado Alfa, almejava se inscrever em um concurso público para o provimento de cargos de médico no Município Beta. Ao se inteirar da possibilidade de cumular ambos os cargos, concluiu corretamente que','{"A": "não poderá cumular os cargos, já que um deles tem natureza civil, enquanto o outro é militar.", "B": "não poderá cumular os cargos, já que o vínculo seria estabelecido nos entes federativos distintos.", "C": "poderá cumular os cargos, pois a vedação constitucional à cumulação somente é aplicada no mesmo nível federativo, não em níveis diversos.", "D": "poderá cumular os cargos, com prevalência da atividade militar, sendo a remuneração de cada qual cotejada com o respectivo teto remuneratório.", "E": "poderá cumular os cargos, pois são privativos de profissionais de saúde, com profissões regulamentadas, mas a soma da remuneração não pode superar o teto remuneratório."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',46,'Direito Constitucional',null,'Após ampla mobilização dos Deputados Estaduais, a Constituição do Estado Alfa foi reformada, passando a dispor sobre a competência das Comissões da Assembleia Legislativa para a colheita de manifestações de pessoas que possam contribuir com suas atividades. Com esse objetivo, foi autorizada a convocação das seguintes autoridades: (1) Secretários de Estado; (2) Procurador-Geral do Estado; (3) Procurador-Geral de Justiça; e (4) Presidentes de autarquias e de fundações com personalidade jurídica de direito público. Acresça-se que o não atendimento à convocação caracterizaria infração político-administrativa. Irresignado com o teor da reforma, o Partido Político Delta consultou sua assessoria a respeito da compatibilidade desse comando normativo com a Constituição da República, sendo-lhe corretamente respondido que','{"A": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 1, 3 e 4.", "B": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 2, 3 e 4.", "C": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 2 e 3.", "D": "somente é compatível com a ordem constitucional a convocação das autoridades referidas em 1 e 2.", "E": "é compatível com a ordem constitucional a convocação das autoridades referidas em 1, 2, 3 e 4."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',47,'Direito Constitucional',null,'O Presidente da República editou a Medida Provisória nº X, que tem por objetivo a disponibilização de recursos para a realização de despesas não previstas na lei orçamentária anual, o que decorreu da existência de uma situação imprevista, em que se decidiu pelo desenvolvimento de determinada política pública de interesse da coletividade. À luz da sistemática constitucional, é correto afirmar que a Medida Provisória nº X é','{"A": "constitucional, pois ela dispôs sobre créditos suplementares.", "B": "inconstitucional, pois ela dispôs sobre créditos especiais, o que é vedado.", "C": "inconstitucional, pois a abertura de créditos extraordinários exige a edição de lei em sentido formal.", "D": "inconstitucional, pois a medida provisória não pode dispor sobre nenhuma espécie de crédito adicional.", "E": "constitucional, considerando que a abertura de créditos extraordinários deve ser realizada por medida provisória."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',48,'Direito Constitucional',null,'Maria, Deputada Estadual, constatou que o Governador do Estado editou um decreto que, ao seu ver, não só ultrapassava os balizamentos oferecidos pela Lei Complementar nº X como a afrontava diretamente. Irresignada com esse ato, que reputava flagrantemente dissonante da separação dos poderes, Maria solicitou que sua assessoria analisasse a medida a ser adotada, no âmbito da Assembleia Legislativa, em relação ao ato praticado pelo Governador. A assessoria respondeu corretamente, à luz da sistemática estabelecida na Constituição da República, que a Assembleia Legislativa pode','{"A": "revogar o decreto, a partir do reconhecimento de sua inconstitucionalidade, por afronta à separação dos poderes.", "B": "impedir a efetividade do decreto, embora não possa incursionar no âmbito de sua validade e eficácia.", "C": "reconhecer a incompatibilidade do decreto com a Lei Complementar nº X, sustando-o.", "D": "declarar a inconstitucionalidade do decreto, o que importa no reconhecimento de sua nulidade.", "E": "impetrar mandado de segurança, para que o Poder Judiciário declare a ilegalidade do ato."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',49,'Direito Constitucional',null,'Joana, brasileira nata, que era funcionária contratada do Ministério das Relações Exteriores do País Alfa, recebeu, de seu superior hierárquico, a incumbência de identificar, à luz da ordem constitucional brasileira, o que deve ser feito para que o representante diplomático do País Alfa possa atuar no território da República Federativa do Brasil. Após percuciente análise, Joana concluiu corretamente que o referido representante diplomático deve','{"A": "receber o exequatur do Presidente da República.", "B": "ser aceito pelo Presidente da República, com posterior referendo do Senado Federal.", "C": "ser acreditado pelo Presidente da República, independente de manifestação do Poder Legislativo.", "D": "ser necessariamente aceito pela República Federativa do Brasil, por ser representante do Estado Alfa.", "E": "ser aprovado pelo Senado Federal e, uma vez aceito, receber a carta de recepção do Presidente da República."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',50,'Direito Constitucional',null,'Pedro, Deputado Estadual, no mês imediatamente anterior à posse nesse cargo, aceitara atuar como diretor executivo de uma sociedade empresária concessionária de serviço público de transporte intermunicipal, vínculo este que cessou no dia anterior à sua posse. Alguns meses depois, em um debate envolvendo projeto de lei que versava sobre a agência reguladora estadual, que deveria atuar no âmbito da generalidade dos serviços públicos desse nível federativo, Mário, também Deputado Estadual, informou que Pedro não tinha isenção para participar do debate, tornando pública a referida informação. À luz da sistemática estabelecida na Constituição da República, é correto afirmar que a conduta de Pedro','{"A": "não é juridicamente ilícita.", "B": "é ilícita e deve acarretar, como consequência, a perda do mandato.", "C": "será lícita ou ilícita conforme dispuser a Constituição Estadual e o regimento interno da Assembleia Legislativa.", "D": "é ilícita, mas, com a posse, ocorreu a preclusão de qualquer medida que poderia ser adotada em seu desfavor.", "E": "é lícita, já que as vedações incidentes sobre os Deputados Estaduais somente se tornam operativas após a posse."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',51,'Direito Constitucional',null,'Um assessor do Presidente da República o informou a respeito do recebimento de relatórios de diversos Ministros de estado, apontando a existência de inúmeros cargos vagos em suas estruturas e pela existência de outros cargos que se encontravam ocupados e se mostravam desnecessários. Por tal razão, propuseram a extinção desses cargos. O assessor informou corretamente ao Presidente da República que ele, caso acolha os argumentos apresentados, deve','{"A": "propor ao Poder Legislativo, com base no princípio da paridade das formas, a extinção desses cargos, sendo demitidos os servidores estáveis que estejam ocupando os cargos extintos.", "B": "extinguir os cargos vagos e declarar a desnecessidade dos cargos ocupados, sendo postos em disponibilidade, neste último caso, os servidores estáveis que os ocupem.", "C": "propor ao Poder Legislativo a extinção dos cargos vagos e aguardar que os cargos atualmente ocupados fiquem vagos, para que seja proposta a sua extinção.", "D": "declarar a desnecessidade dos cargos vagos e dos cargos ocupados, o que impedirá novas nomeações, até que sejam extintos pelo Poder Legislativo.", "E": "extinguir os cargos vagos e os cargos ocupados, sendo postos em disponibilidade, neste último caso, todos os servidores que os ocupem."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',52,'Direito Constitucional',null,'O Presidente do Tribunal de Justiça do Estado Alfa foi informado por sua assessoria que já era o momento de serem adotadas as providências relacionadas ao orçamento do ano vindouro, uma vez que o denominado “ciclo orçamentário”, que abrange o conjunto de medidas que culminarão com a elaboração da lei orçamentária anual do próximo exercício financeiro, estava prestes a se iniciar. Em relação às medidas relacionadas ao referido “ciclo orçamentário”, a assessoria respondeu corretamente que','{"A": "o Tribunal de Justiça deve estipular, juntamente com os demais Poderes, na lei de diretrizes orçamentárias, os limites de sua proposta orçamentária.", "B": "a proposta orçamentária do Tribunal de Justiça deve ser submetida ao Poder Legislativo no prazo estabelecido pela ordem constitucional, observados os limites estabelecidos pela lei de diretrizes orçamentárias.", "C": "a proposta orçamentária será encaminhada, pelo Tribunal de Justiça, ao Poder Executivo, que a compatibilizará com as propostas das estruturas estatais de poder, de modo a assegurar o equilíbrio orçamentário.", "D": "caso o Tribunal de Justiça não encaminhe sua proposta orçamentária no prazo estabelecido pela lei de diretrizes orçamentárias, o Poder Legislativo irá considerar os valores da lei orçamentária vigente, corrigidos monetariamente.", "E": "a proposta orçamentária do Tribunal de Justiça deve observar a desvalorização da moeda desde a aprovação da última lei orçamentária, devendo ser encaminhada ao Poder Legislativo após manifestação da Secretaria de Estado competente."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',53,'Direito Constitucional',null,'O Presidente da Assembleia Legislativo do Estado Alfa praticou ato que, ao ver do Deputado Estadual João, era manifestamente contrário à Constituição Estadual e ao Regimento Interno da Casa Legislativa, o que o levou a impetrar mandado de segurança perante o Órgão Especial do Tribunal de Justiça. A ordem, no entanto, foi denegada com base em um argumento manifestamente contrário à Constituição da República. À luz da sistemática constitucional, é correto afirmar que, em sendo preenchidos os demais requisitos exigidos','{"A": "não é cabível a interposição de recurso a nenhum tribunal nacional, considerando que as normas discutidas na impetração têm natureza estadual.", "B": "pode ser interposto recurso especial, a ser processado e julgado pelo Superior Tribunal de Justiça.", "C": "pode ser interposto recurso extraordinário, a ser processado e julgado pelo Supremo Tribunal Federal.", "D": "pode ser interposto recurso ordinário a ser processado e julgado pelo Superior Tribunal de Justiça.", "E": "pode ser impetrado mandado de segurança perante o Supremo Tribunal Federal."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',54,'Direito Constitucional',null,'Um grupo armado, formado por agentes públicos vinculados ao Estado Alfa, desferiu disparos de arma de fogo, que foram a causa eficiente da morte de dezena de pessoas, sendo todas elas familiares de indivíduos alegadamente envolvidos com a criminalidade. Por entenderem que as forças de segurança do Estado estariam possivelmente mancomunadas com os autores do ilícito, não realizando a apuração da forma devida, pessoas próximas às vítimas decidiram consultar um advogado a respeito da possibilidade de a apuração ser deslocada para a Justiça Federal. O advogado respondeu corretamente que','{"A": "é possível o deslocamento de competência, o que pode ser requerido por legítimo interessado ao Tribunal Regional Federal competente.", "B": "é possível o deslocamento de competência, o que deve ser requerido por legitimado específico e deferido pelo tribunal nacional competente.", "C": "ocorreu a perpetuatio jurisdictionis, não sendo possível a alteração de competência após a prática do ilícito, sob pena de configuração de um juízo de exceção.", "D": "é possível o deslocamento de competência, desde que isto seja deferido pelo tribunal nacional competente, mas apenas na fase processual, não durante o inquérito.", "E": "é possível o deslocamento de competência, desde que demonstrada, perante o Supremo Tribunal Federal, a existência de causa de suspeição ou impedimento."}'::jsonb,'B',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',55,'Direito Constitucional',null,'Maria logrou êxito em ser aprovada no processo seletivo destinado ao preenchimento das vagas no Mestrado em Odontologia oferecido pela Universidade Estadual XX. Ao comparecer, no dia e no local indicados, para a realização de matrícula, foi surpreendida com a informação de que deveria efetuar o pagamento da taxa de matrícula. Irresignada com o teor dessa informação, consultou o seu advogado a respeito da correção dessa cobrança à luz da Constituição da República, sendo-lhe corretamente informado que a cobrança estava','{"A": "certa, considerando a autonomia universitária para definir que atividades acadêmicas podem ensejar a referida cobrança.", "B": "errada, considerando a necessária gratuidade do ensino público a nível de pós-graduação, lato sensu ou stricto sensu.", "C": "errada, considerando a gratuidade do ensino público nos distintos níveis da educação formal com graus reconhecidos.", "D": "certa, considerando que a gratuidade do ensino público somente é impositiva até o nível de graduação.", "E": "errada, desde que Maria demonstre a sua hipossuficiência econômica, o que lhe assegura a gratuidade."}'::jsonb,'C',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',56,'Direito Constitucional',null,'João, pessoa hipossuficiente, necessitava de uma intervenção cirúrgica para restabelecer o alinhamento de sua coluna e evitar a compressão setorial de alguns nervos, o que vinha lhe causando dores insuportáveis. Após uma exaustiva procura de vaga para a operação em diversos hospitais públicos, obtendo sempre respostas negativas, João decidiu ingressar com uma ação judicial em face do ente competente, visando a compeli-lo a realizar a cirurgia, que se afigurava urgente. À luz da sistemática constitucional, a ação deve ser ajuizada em face','{"A": "da União, considerando a sua posição de mantenedora do sistema brasileiro de saúde.", "B": "do Município no qual João reside, considerando a predominância do interesse local.", "C": "do Estado no qual João reside, considerando a sua obrigação primária de atender aos casos mais complexos.", "D": "do Município no qual João reside, do Estado no qual João reside ou da União, em conjunto ou isoladamente.", "E": "do ente federativo cuja legislação contemple a obrigação de ser realizada a cirurgia de João em seu sistema de saúde."}'::jsonb,'D',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',57,'Direito Constitucional',null,'A Lei federal nº X dispôs que as pessoas jurídicas que se encontrassem em débito com o sistema de seguridade social, observado o período de endividamento ali estabelecido, estariam impossibilitadas de celebrar contratos com o Poder Público dos distintos níveis federativos. Em razão de grave crise econômica, que aumentou o nível de endividamento das pessoas jurídicas, sobreveio a Lei federal nº Y, que não só suprimiu a vedação como determinou que seria assegurado a essas pessoas jurídicas o recebimento dos incentivos fiscais e creditícios que indicava. Irresignado com o teor da Lei federal nº Y, o Partido Político Alfa, com representação no Congresso Nacional, consultou o seu advogado a respeito da constitucionalidade deste diploma normativo, sendo-lhe corretamente respondido que ele era','{"A": "constitucional, por integrar a eficácia do princípio do livre desenvolvimento sustentável.", "B": "inconstitucional, pois contrariou determinação constitucional, cuja eficácia foi integrada pela Lei federal nº X.", "C": "constitucional, pois se limitou a afastar a incidência das “sanções políticas” ilicitamente estabelecidas pela Lei federal nº X.", "D": "constitucional, pois a União, conforme a sua valoração política, tem a opção de adotar tanto a sistemática da Lei federal nº X como a da Lei nº Y.", "E": "inconstitucional, por afrontar o princípio constitucional da isonomia, na parte em que direcionou incentivos fiscais e creditícios apenas às pessoas jurídicas em débito."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',58,'Direito Constitucional',null,'A Constituição do Estado Alfa foi objeto de emenda em relação à disciplina das competências do Tribunal de Contas Estadual. De acordo com a disciplina estabelecida pela emenda, as contas de governo apresentadas pelos chefes dos poderes municipais seriam julgadas pelas Câmaras Municipais, considerando o parecer prévio do Tribunal de Contas, que somente deixaria de prevalecer por decisão de dois terços dos membros dessas Câmaras. À luz da sistemática estabelecida na Constituição da República, é correto afirmar que a referida emenda é','{"A": "materialmente constitucional, pois reproduz comandos já veiculados pela Constituição da República.", "B": "materialmente inconstitucional, pois as Câmaras Municipais somente têm competência para julgar as contas do Chefe do Poder Executivo.", "C": "formalmente inconstitucional, pois, em razão da autonomia dos Municípios, a matéria deveria ser disciplinada nas leis orgânicas municipais.", "D": "formal e materialmente constitucional, pois cabe às Constituições estaduais veicular as regras e os princípios aos quais estão vinculados os Municípios.", "E": "materialmente inconstitucional, pois fere a autonomia municipal o quórum qualificado de votação para que deixe de prevalecer o parecer do Tribunal de Contas."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',59,'Direito Constitucional',null,'Em razão do crescimento do número de roubos, mediante o emprego de arma de fogo, no território do Estado Alfa, foi editada a Lei estadual nº X. De acordo com esse diploma normativo, que foi objeto de severas críticas por parte da entidade representativa das instituições financeiras, era obrigatória, sob pena de multa, a instalação de equipamentos de segurança nas agências bancárias. Além das críticas, foram obtidos diversos provimentos jurisdicionais nos quais era desautorizada a aplicação da Lei estadual nº X sob o argumento de sua inconstitucionalidade. À luz dessa narrativa, é correto afirmar que a Lei estadual nº X é','{"A": "constitucional, porque o Estado pode legislar em matérias afetas à segurança pública.", "B": "inconstitucional, por afrontar a competência privativa da União para legislar sobre segurança pública.", "C": "inconstitucional, por afrontar a competência dos Municípios para legislar sobre assuntos de interesse local.", "D": "constitucional, considerando que as regras afetas às construções edilícias devem ser uniformizadas em lei estadual.", "E": "não pode ser objeto de ação ajuizada perante o Supremo Tribunal Federal cujo pedido seja o reconhecimento de sua constitucionalidade."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Consultor Legislativo Especial – Direito Constitucional',2023,null,'Tipo 1',60,'Direito Constitucional',null,'Em determinado exercício financeiro, Josué, Deputado Estadual, constatou que o Governador do Estado do Maranhão, até o dia 31 de março, ainda não tinha apresentado as contas concernentes ao exercício pretérito. Ao constatar essa omissão, Josué consultou sua assessoria a respeito das medidas passíveis de serem adotadas pela Assembleia Legislativa do Estado do Maranhão em relação a esse proceder. A assessoria respondeu corretamente, à luz da Constituição Estadual, que a Assembleia Legislativa','{"A": "deve proceder à tomada de contas.", "B": "pode solicitar que o Tribunal de Contas proceda à tomada de contas especial.", "C": "deve requisitar que o Tribunal de Contas proceda à tomada de contas especial.", "D": "deve aguardar o exaurimento do prazo constitucional e, persistindo a omissão, proceder à tomada de contas.", "E": "deve aguardar o término do exercício financeiro e, persistindo a omissão, proceder à tomada de contas."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cns101-consultor-legislativo-especial-direito-constitucionalcns101-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno')
insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',1,'Língua Portuguesa',null,'O título “Z de depressão” captura, de forma concisa, a ideia central do texto 1. Essa mesma ideia é retomada, de maneira mais detalhada, na seguinte passagem:','{"A": "“Até os 8 anos, levou a vida tranquila de alguém que cresce numa cidade pequena”;", "B": "“Mas então um dos seus tios se matou”;", "C": "“um quadro de adoecimento mental de crianças e jovens brasileiros, com casos repetidos de depressão, ansiedade e síndrome do pânico”;", "D": "“Como as escolas estavam fechadas e seria perigoso realizar as entrevistas presencialmente, só participaram aqueles com conexão à internet”;", "E": "“O Boletim Epidemiológico do Ministério da Saúde não aponta causas exatas do sofrimento mental dos jovens brasileiros”."}'::jsonb,'C',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',2,'Língua Portuguesa',null,'A sequência que funciona como título do texto 1 (“Z de depressão”) é um jogo de palavras, isto é, uma espécie de brincadeira linguística. A força expressiva dessa sequência decorre do fato de que ela:','{"A": "rebate, de maneira assertiva, um comentário hostil sobre a saúde mental dos brasileiros;", "B": "esclarece, de maneira irônica, o significado de uma palavra contida no próprio título;", "C": "observa, de maneira casual, uma contradição inerente ao problema relatado;", "D": "evoca, de maneira implícita, uma outra construção da língua portuguesa;", "E": "oferece, de maneira ponderada, uma solução alternativa para um problema social."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',3,'Língua Portuguesa',null,'O texto 1 se estrutura de forma indutiva, organizando-se do particular (parágrafos 1 e 2) para o geral (parágrafos 3, 4 e 5). Essa mudança do particular para o geral é acompanhada por uma passagem:','{"A": "de um modo de organização narrativo-descritivo para um modo de organização expositivo;", "B": "de um modo de organização descritivo-argumentativo para um modo de organização expositivo;", "C": "de um modo de organização narrativo-injuntivo para um modo de organização argumentativo;", "D": "de um modo de organização narrativo-argumentativo para um modo de organização argumentativo;", "E": "de um modo de organização expositivo-argumentativo para um modo de organização descritivo. Tipo 1 – Branca – Página 4"}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',4,'Língua Portuguesa',null,'“Cresceu encontrando pequenos alívios para a angústia: cachorros, namoradas, bebidas alcoólicas, cortes nos braços.” Nessa passagem, retirada do texto 1, uma enumeração de elementos é encerrada com vírgula – e não, como seria mais usual, com a conjunção aditiva “e”. Nesse contexto, a omissão da conjunção aditiva produz o efeito de:','{"A": "caracterizar um personagem secundário;", "B": "sugerir uma lista não exaustiva;", "C": "expressar uma opinião implícita;", "D": "enunciar uma proposição autoevidente;", "E": "enfatizar uma posição ideológica."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',5,'Língua Portuguesa',null,'“Mas então um dos seus tios se matou, e o menino foi se tornando cada vez mais triste.” A passagem acima, retirada do texto 1, mostra que a conjunção “e” pode veicular ideia de conclusão. Outra passagem do mesmo texto em que essa conjunção apresenta valor conclusivo é:','{"A": "“Ele tem 21 anos e mora em Luz”;", "B": "“Na adolescência, Caio identificou que era um homem transgênero, e sua sensação de isolamento só cresceu”;", "C": "“Em um Boletim Epidemiológico divulgado setembro passado, o Ministério da Saúde apontava que as taxas de suicídio saltaram 116% entre crianças e adolescentes de 5 a 14 anos”;", "D": "“Como as escolas estavam fechadas e seria perigoso realizar as entrevistas presencialmente, só participaram aqueles com conexão à internet”;", "E": "“Ainda assim, os resultados indicaram que a insegurança alimentar esteve associada a maiores níveis de ansiedade e a sintomas depressivos”."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',6,'Língua Portuguesa',null,'“Ainda assim, os resultados indicaram que a insegurança alimentar esteve associada a maiores níveis de ansiedade e a sintomas depressivos.” Nessa passagem, retirada do quarto parágrafo do texto 1, o conector “Ainda assim” indica que a informação subsequente irá contrariar uma expectativa do leitor. A alternativa em que essa expectativa contrariada está formulada de modo adequado é:','{"A": "a geração Z, por ser formada por pessoas atualmente jovens, tenderá a não sofrer problemas de saúde mental;", "B": "pessoas trans, por terem poucas informações sobre a própria condição, são mais vulneráveis a ansiedade e depressão;", "C": "a insegurança alimentar, por ser própria de países em desenvolvimento, tenderá a ser detectada em estudos sobre a realidade brasileira;", "D": "dados de pesquisas, por serem enviesados, tendem a distorcer a realidade;", "E": "pessoas mais pobres, por terem menos acesso à internet, não terão seus problemas econômicos refletidos na pesquisa."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',7,'Língua Portuguesa',null,'“Virou alvo de bullying na escola, perdeu os amigos – ‘não sobrou ninguém’, ele conta. Aos 10 anos, tentou suicídio e precisou ser internado às pressas.” A proposta de adaptação dessa passagem do texto 1 em que o trecho em discurso direto está corretamente transposto para o discurso indireto livre é:','{"A": "Virou alvo de bullying na escola, perdeu os amigos – “não sobrou ninguém”, conta ele. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "B": "Virou alvo de bullying na escola, perdeu os amigos. Ele conta: “não sobrou ninguém”. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "C": "Virou alvo de bullying na escola, perdeu os amigos. Quando se deu conta, tomou um susto. Não havia sobrado ninguém. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "D": "Virou alvo de bullying na escola, perdeu os amigos. Ele conta que não sobrou ninguém. Aos 10 anos, tentou suicídio e precisou ser internado às pressas;", "E": "Virou alvo de bullying na escola, perdeu os amigos. Ele contou que não sobrara ninguém. Aos 10 anos, tentou suicídio e precisou ser internado às pressas."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',8,'Língua Portuguesa',null,'“Na adolescência, Caio identificou que era um homem transgênero, e sua sensação de isolamento só cresceu. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Embora os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...]” Essa passagem, retirada do texto 1, pode ser reescrita, sem modificação do sentido original e sem desvio em relação à norma padrão do português, da seguinte forma:','{"A": "Na adolescência, Caio identificou que era um homem transgênero, e sua sensação de isolamento só cresceu. Em função do agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Ainda que os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...];", "B": "Caio identificou na adolescência, que era um homem transgênero, e sua sensação de isolamento só cresceu. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Ainda que os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...];", "C": "Na adolescência, Caio descobriu que era um homem transgênero, razão pela qual, sua sensação de isolamento só cresceu. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Mesmo os médicos tendo recomendado, ele nunca tratou a depressão, por um longo período de tempo. [...];", "D": "Caio na adolescência, identificou ser um homem transgênero, e sua sensação de isolamento só cresceu. Não obstante o agravamento do seu quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Embora os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...];", "E": "Na adolescência, Caio identificou que era um homem transgênero, o que implicou no crescimento da sua sensação de isolamento. Com o agravamento do quadro depressivo, foi levado ao hospital algumas vezes depois de se automutilar. Embora os médicos tenham recomendado, ele nunca tratou a depressão por um longo período de tempo. [...]. Tipo 1 – Branca – Página 5"}'::jsonb,'A',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',9,'Língua Portuguesa',null,'“Os dados levaram o governo federal a classificar o suicídio como ‘um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens’.” Essa passagem, retirada do texto 1, pode ser reescrita de diversas maneiras. A reescritura em que NÃO se verifica nenhum erro relativo ao acento indicativo de crase é:','{"A": "Face a esses dados, o governo federal classificou o suicídio como um problema de saúde pública crescente no Brasil, com destaque as faixas etárias mais jovens;", "B": "Os dados levaram a classificação do suicídio, por parte do governo federal, como um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens;", "C": "Em reação a esses dados, o governo federal procedeu à classificação do suicídio como um problema de saúde pública crescente no Brasil, sobretudo no que se refere às faixas etárias mais jovens;", "D": "Face à informações como essas, o governo federal passou a tratar o suicídio como um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens;", "E": "Reagindo as descobertas do Boletim Epidemiológico, o governo federal passou à classificar o suicídio como um problema de saúde pública crescente no Brasil, com destaque aos grupos etários mais jovens."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',10,'Língua Portuguesa','Texto 2 A nova era do divórcio (fragmento) “‘Novelas da Globo aumentam o número de divórcios no Brasil.’ Parece fake news de haters, mas não. Trata-se de um dado histórico. A conclusão é de um estudo de 2009, feito pelo Banco Interamericano de Desenvolvimento (BID). A pesquisa fez um cruzamento entre informações de censos das décadas de 1970, 1980 e 1990 e dados sobre a expansão do sinal da Globo no país. Segundo os autores do estudo, o número de mulheres que se separaram aumentou conforme a teledramaturgia da emissora foi chegando a mais cidades. ‘A exposição a estilos de vida modernos mostrados na TV, a funções desempenhadas por mulheres emancipadas e a uma crítica aos valores tradicionais mostrou estar associada aos aumentos nas frações de mulheres separadas e divorciadas nas áreas municipais brasileiras’, diz a pesquisa. [...] O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21, por um motivo ainda mais insuspeito: a disseminação de um vírus. Segundo o Colégio Notarial do Brasil, que congrega os tabeliães de notas e protestos, no primeiro ano da pandemia, em 2020, houve um aumento de 15% no número de divórcios em comparação com o ano anterior. Em 2021, então, o número de casais que oficializaram a separação bateu recorde: 80.573 divórcios consensuais, o maior da série histórica, que é registrada desde 2007. [...] Sim, o início desnorteante da pandemia foi o gatilho para um boom de divórcios planeta afora. Motivos para a escalada nas tensões entre casais não faltaram, você sabe: o encarceramento no lar de ambos os cônjuges (condição que se estendeu indefinidamente para quem aderiu ao home office), perrengues financeiros, a necessidade de lidar com as crianças estudando em casa, distúrbios psicológicos (ansiedade, depressão, paranoia…). [...] A [empresa americana] Legal Templates mostrou que os casados há menos de cinco anos foram os que mais se separaram em 2020: 58%. Aliás, quanto menor o tempo de união oficial, maior o aumento no índice de cada um para o seu lado. Enquanto, em 2019, pré-Covid, apenas 11% dos que se separaram tinham menos de cinco meses sob o mesmo teto, em 2020 essa porcentagem quase dobrou: foi para 20%. Estudiosos que analisaram esses dados chegaram a uma conclusão que faz sentido: casais que haviam se unido havia pouco tempo são menos calejados para enfrentar o maremoto que atingiu a praia conjugal na onda do vírus. Os parceiros mais longevos já tinham passado por outras crises. Talvez ilesos, talvez feridos. E muitos aprenderam a sair delas juntos. [...] Nesta nova era do divórcio, vale um alerta: mesmo nas separações mais amigáveis – e até afetuosas –, romper um relacionamento de anos segue sendo tão difícil quanto sempre foi. Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos difíceis e de pisar em ovos. Se você se separou, vale a pena um esforço a mais para manter o bom convívio. Não apenas pelo bem dos filhos – se o casamento produziu crianças. É importante honrar uma história que, em boa parte do tempo, foi partilhada com a pessoa que um dia você amou como se fosse a única.” Disponível em: https://super.abril.com.br/comportamento/a-nova-era-do-divorcio. Acesso em: 24/07/2022 Tipo 1 – Branca – Página 6','É possível identificar, no texto 2, três blocos estruturais simétricos: um primeiro formado pelos parágrafos 1 e 2; um segundo formado pelos parágrafos 4 e 5; e um terceiro formado pelos parágrafos 6 e 7. Como a organização é paralelística, os primeiros parágrafos de cada par (isto é, os parágrafos 1, 4 e 6) desempenham sempre uma mesma função textual, assim como os segundos parágrafos de cada par (isto é, os parágrafos 2, 5 e 7). As funções textuais desempenhadas pelos parágrafos 1, 4 e 6, de um lado, e 2, 5 e 7, de outro, estão corretamente caracterizadas, respectivamente, na seguinte alternativa:','{"A": "veicular um enunciado irônico e refutar opiniões contrárias;", "B": "estabelecer uma correlação e fornecer a causa subjacente;", "C": "levantar uma hipótese e enumerar suas consequências imediatas;", "D": "caracterizar uma situação e narrar os eventos decorrentes;", "E": "enfatizar um problema e propor uma solução concreta."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',11,'Língua Portuguesa',null,'O texto 2 elenca diversos fatores relacionados ao aumento de casos de divórcio. Esses fatores podem ser divididos em três grupos: causas indiretas (ou mediatas), causas diretas (ou imediatas) e facilitadores. A alternativa que apresenta, respectivamente, uma causa indireta, uma causa direta e um facilitador é:','{"A": "expansão do sinal da Rede Globo, exposição de estilos de vida modernos e encarceramento de ambos os cônjuges;", "B": "encarceramento de ambos os cônjuges, perrengues financeiros e necessidade de lidar com crianças estudando em casa;", "C": "distúrbios psicológicos, falta de experiência com crises prévias e críticas aos valores tradicionais;", "D": "pandemia de Covid-19, encarceramento de ambos os cônjuges e pouco tempo de casamento;", "E": "exposição de funções desempenhadas por mulheres emancipadas, pandemia de Covid-19 e adesão ao home office."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',12,'Língua Portuguesa',null,'O último parágrafo do texto 2 recorre a uma estratégia de construção textual bastante comum em parágrafos de conclusão de reportagens de divulgação científica. Essa estratégia consiste na adoção:','{"A": "do subjuntivo como modo verbal predominante, com o objetivo de relatar eventos hipotéticos;", "B": "de conjunções causais, com o objetivo de estabelecer relações lógicas de causa e efeito;", "C": "de substantivos ligados ao jargão acadêmico, com o objetivo de conferir credibilidade ao texto;", "D": "de um registro fortemente irônico, com o objetivo de provocar surpresa no leitor;", "E": "da injunção como tipo textual primário, com o objetivo de aconselhar o leitor."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',13,'Língua Portuguesa',null,'“O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21, por um motivo ainda mais insuspeito: a disseminação de um vírus.” Retirado do texto 2, esse fragmento sugere, implicitamente, que a correlação entre aumento do número de divórcios e expansão do sinal da Rede Globo é insuspeita. Essa mesma ideia pode ser flagrada na seguinte passagem:','{"A": "“Parece fake news”;", "B": "“Trata-se de um dado histórico”;", "C": "“o número de mulheres que se separaram aumentou”;", "D": "“A exposição a estilos de vida modernos mostrados na TV”;", "E": "“aumentos nas frações de mulheres separadas e divorciadas nas áreas municipais brasileiras”."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',14,'Língua Portuguesa',null,'“A [empresa americana] Legal Templates mostrou que os casados há menos de cinco anos foram os que mais se separaram em 2020: 58%. Aliás, quanto menor o tempo de união oficial, maior o aumento no índice de cada um para o seu lado.” Na passagem acima, retirada do texto 2, o conector “aliás”, ao mesmo tempo em que contribui para a coesão textual, introduz uma sequência que desempenha a função de:','{"A": "corrigir um erro;", "B": "estabelecer uma generalização;", "C": "explicitar uma contradição;", "D": "resumir uma explicação;", "E": "avaliar uma proposta."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',15,'Língua Portuguesa',null,'“Segundo o Colégio Notarial do Brasil, que congrega os tabeliães de notas e protestos, no primeiro ano da pandemia, em 2020, houve um aumento de 15% no número de divórcios em comparação com o ano anterior. Em 2021, então, o número de casais que oficializaram a separação bateu recorde [...]” Muitas gramáticas ensinam que o “então” é uma conjunção conclusiva. No entanto, na passagem acima, retirada do texto 2, essa palavra apresenta um uso distinto, que é próprio do registro informal e não costuma figurar nos compêndios gramaticais. Esse mesmo uso está presente no seguinte exemplo:','{"A": "Eu estava meio triste, então resolvi ficar em casa.", "B": " Você já tem uma resposta pra mim?  Então... eu já pensei bastante, mas ainda não sei o que responder.", "C": " Então, vamos?", "D": "Até então, eu ainda não havia tomado uma decisão.", "E": "Se você acha que 50 convidados é muita gente, 100, então, nem se fala. Tipo 1 – Branca – Página 7"}'::jsonb,'E',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',16,'Língua Portuguesa',null,'“Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos difíceis e de pisar em ovos.” Essa passagem, retirada do texto 2, apresenta uma marca de informalidade. A proposta de reescritura em que essa marca é substituída por uma palavra ou expressão mais formal sem que haja alteração substancial de significado é:','{"A": "Os primeiros tempos são, em geral, um período deprimente, de luto mesmo, acordos difíceis e de pisar em ovos;", "B": "Os primeiros anos tendem a ser um período deprimente, de enlutamento mesmo, acordos difíceis e de pisar em ovos;", "C": "Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, pactos difíceis e de pisar em ovos;", "D": "Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos complexos e de pisar em ovos;", "E": "Os primeiros tempos tendem a ser um período deprimente, de luto mesmo, acordos complexos e atitudes cautelosas."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',17,'Língua Portuguesa',null,'Em cada uma das alternativas abaixo, encontra-se, nesta ordem, uma passagem transcrita do texto 2 e uma proposta de reescritura dessa mesma passagem. Assinale a alternativa na qual, ao mesmo tempo, a passagem transcrita do texto 2 seja ambígua (desconsiderando-se nosso conhecimento de mundo) e a proposta de reescritura apresentada desfaça essa ambiguidade:','{"A": "“Em 2021, então, o número de casais que oficializaram a separação bateu recorde” / Em 2021, então, bateu recorde o número de casais que oficializaram a separação;", "B": "“Estudiosos que analisaram esses dados chegaram a uma conclusão que faz sentido” / Analisando esses dados, estudiosos chegaram a uma conclusão que faz sentido;", "C": "“O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21” / O que os estudiosos do BID não poderiam prever, no Brasil do século 21, é o quanto os divórcios aumentariam;", "D": "“[...] o encarceramento no lar de ambos os cônjuges (condição que se estendeu indefinidamente para quem aderiu ao home office) [...]” / o encarceramento de ambos os cônjuges no lar (condição que se estendeu indefinidamente para quem aderiu ao home office);", "E": "“Segundo os autores do estudo, o número de mulheres que se separaram aumentou conforme a teledramaturgia da emissora foi chegando a mais cidades” / De acordo com os autores do estudo, o número de mulheres que se separaram aumentou conforme a teledramaturgia da emissora foi chegando a mais cidades."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',18,'Língua Portuguesa',null,'Embora tanto o texto 1 quanto o texto 2 pertençam ao gênero textual reportagem, o segundo exibe uma linguagem mais informal que o primeiro. Essa maior informalidade é evidenciada pela presença, no texto 2, de:','{"A": "estrangeirismos recentes e marcas de interlocução direta;", "B": "orações subordinadas adjetivas e discurso indireto livre;", "C": "gírias associadas à fala jovem e paralelismos sintáticos;", "D": "frases nominais e abreviações;", "E": "regionalismos e verbos impessoais."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',19,'Língua Portuguesa',null,'Embora os textos 1 e 2 pertençam ao gênero textual reportagem, eles correspondem a subgêneros distintos. Em particular, apenas o texto 2 se qualifica como uma reportagem de divulgação científica. Um reflexo dessa especificidade é o fato de que apenas o texto 2 inclui metáforas criativas (isto é, inovadoras, não convencionalizadas), como pode ser visto na seguinte passagem:','{"A": "“‘Novelas da Globo aumentam o número de divórcios no Brasil’”;", "B": "“A conclusão é de um estudo de 2009, feito pelo Banco Interamericano de Desenvolvimento (BID)”;", "C": "“A [empresa americana] Legal Templates mostrou que os casados há menos de cinco anos foram os que mais se separaram em 2020”;", "D": "“[...] casais que haviam se unido havia pouco tempo são menos calejados para enfrentar o maremoto que atingiu a praia conjugal na onda do vírus”;", "E": "“[...] mesmo nas separações mais amigáveis – e até afetuosas , romper um relacionamento de anos segue sendo tão difícil quanto sempre foi”."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',20,'Língua Portuguesa',null,'“O Boletim Epidemiológico do Ministério da Saúde não aponta causas exatas do sofrimento mental dos jovens brasileiros, mas dá a entender que certas particularidades ajudariam a explicar o aumento das taxas de suicídio juvenil.” “O que os estudiosos do BID não poderiam prever é o quanto os divórcios aumentariam no Brasil do século 21.” Nessas passagens, retiradas respectivamente dos textos 1 e 2, as duas formas verbais sublinhadas se encontram no futuro do pretérito. Apesar disso, é possível observar que esse tempo verbal desempenha funções comunicativas distintas em cada um dos casos. As funções comunicativas desempenhadas pelo futuro do pretérito nas passagens acima estão corretamente caracterizadas, respectivamente, em:','{"A": "expressar ordem ou pedido e enfatizar a noção de desejo;", "B": "marcar polidez no intercâmbio conversacional e indicar que o fato expresso é dependente de uma condição;", "C": "sinalizar incerteza em relação à informação expressa e indicar um evento futuro em relação a um tempo passado;", "D": "exprimir uma verdade atemporal e destacar o caráter improvável de uma condição;", "E": "enfatizar um questionamento e sugerir ausência de comprometimento em relação a uma determinada posição. Tipo 1 – Branca – Página 8 Legislação Específica"}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',21,'Direito Administrativo',null,'João, servidor público há mais de uma década, ocupante de cargo de provimento efetivo em determinada estrutura de poder no Estado do Tocantins, foi acusado e condenado, em processo administrativo, pela prática de grave infração disciplinar, o que culminou na sua demissão. Irresignado com a demissão, João ingressou com medida judicial buscando a sua anulação, no que obteve êxito, sendo acolhido o argumento de que as provas utilizadas eram nulas. Considerando os dados da narrativa, deve ser aplicado a João o instituto da:','{"A": "reversão;", "B": "recondução;", "C": "reintegração;", "D": "readaptação;", "E": "disponibilidade."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',22,'Direito Administrativo',null,'Ao analisar a possível competência do Tribunal de Contas do Estado do Tocantins, em relação às operações de crédito a serem realizadas pelo Governo do Estado, João concluiu corretamente que essa atuação era não só necessária, como de indiscutível relevância. Ato contínuo, consultou Pedro a respeito do iter procedimental a ser observado e do seu alcance, sendo-lhe corretamente respondido que:','{"A": "após a solicitação encaminhada pelo Governo, ao Poder Legislativo, para a realização da operação, o Tribunal de Contas emitirá parecer sobre a sua legalidade, legitimidade, economicidade e razoabilidade;", "B": "o Governo deve solicitar a análise inicial ao Tribunal de Contas, que emitirá parecer sobre a legalidade, legitimidade, economicidade e razoabilidade da operação, encaminhando-o ao Poder Legislativo para a decisão final;", "C": "após a solicitação encaminhada pelo Governo, ao Poder Legislativo, para a concretização da operação, o Tribunal de Contas decidirá sobre a sua realização, ou não, considerando a legalidade, legitimidade, economicidade e razoabilidade;", "D": "o Governo deve solicitar a análise inicial ao Tribunal de Contas, que decidirá sobre a legalidade, legitimidade, economicidade e razoabilidade da operação, encaminhando a decisão ao Poder Legislativo, que avaliará a sua conveniência;", "E": "após a solicitação encaminhada pelo Governo, ao Poder Legislativo, para a realização da operação, o Tribunal de Contas emitirá parecer apenas sobre a sua legalidade, cabendo ao Legislativo a análise de legitimidade, economicidade e razoabilidade."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',23,'Direito Administrativo',null,'Joana, recém-ingressa no quadro de servidores do Tribunal de Contas do Estado do Tocantins, analisou o rol de medidas cautelares passíveis de serem adotadas por esse Tribunal, sem necessidade de intervenção do Poder Judiciário. Em sua análise preliminar, chegou à conclusão de que essas medidas seriam: 1. o arresto de bens; 2. o afastamento temporário do dirigente do órgão ou entidade; 3. a exibição de documentos ou dados e bens; e 4. a produção antecipada de provas. Ao se deparar com as conclusões de Joana, Maria, sua colega de setor, observou, corretamente, que não depende(m) da atuação do Poder Judiciário:','{"A": "somente a medida 3;", "B": "somente a medida 4;", "C": "somente as medidas 1 e 2;", "D": "somente as medidas 2, 3 e 4;", "E": "as medidas 1, 2, 3 e 4."}'::jsonb,'D',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',24,'Direito Administrativo',null,'Maria, embora tivesse nível superior, foi aprovada em concurso público e tomou posse em cargo de provimento efetivo de nível médio do Tribunal de Contas do Estado do Tocantins. À luz do Plano de Cargos, Carreiras e Remuneração dos Servidores do Tribunal de Contas do Estado do Tocantins, Maria tem assegurado o direito:','{"A": "à percepção de adicional de qualificação;", "B": "à percepção de adicional de nível superior;", "C": "ao enquadramento na classe que congrega os cargos de nível superior;", "D": "ao enquadramento na classe imediatamente superior àquela em que se encontra;", "E": "ao enquadramento no padrão imediatamente superior, na classe em que se encontra."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',25,'Direito Administrativo',null,'Pedro, servidor do Tribunal de Contas do Estado do Tocantins, durante uma fiscalização, suspeitou que Maria teria sonegado um documento que seria útil à análise a ser realizada pela equipe de fiscalização. Por tal razão, alertou-a das sanções aplicáveis em virtude de sonegação de processo, documento ou informação e obstrução ao livre exercício das atividades de controle externo. Irresignada com a suspeita de Pedro e com o “alerta” que recebera, solicitou que o seu advogado analisasse a compatibilidade dessa conduta com o Código de Ética dos Servidores do Tribunal de Contas do Estado do Tocantins. Foi corretamente respondido a Maria que Pedro agiu em:','{"A": "desacordo com o referido Código, pois deve observar um padrão de discrição na solicitação de documentos;", "B": "harmonia com o referido Código, pois deve fazer alertas dessa natureza, ao fiscalizado, quando necessário;", "C": "desacordo com o referido Código, pois deve manter-se neutro em relação à postura do fiscalizado no decorrer dos trabalhos;", "D": "desacordo com o referido Código, pois somente deve agir em harmonia com juízos de certeza, não com a suposição característica da mera suspeita;", "E": "harmonia com o referido Código, pois deve agir de modo inquisitorial em relação ao fiscalizado, em razão da superior hierarquia do controle externo. Tipo 1 – Branca – Página 9 Noções de Direito"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',26,'Direito Administrativo',null,'O regime jurídico dos servidores públicos do Estado Alfa foi alterado pela Lei nº XX/2020, sendo assegurado determinado benefício pecuniário, de caráter episódico, não contínuo, aos servidores que preenchessem os requisitos objetivos previstos na norma. Dois anos depois, ao ser advertido do crescimento exponencial das despesas com pessoal, o que fora parcialmente influenciado pela criação do referido benefício, o chefe do Poder Executivo apresentou projeto de lei, que resultou na Lei nº YY/2022, extinguindo-o. Após a extinção do benefício, Pedro, pessoa muito distraída, percebeu que preenchera os requisitos para a fruição do benefício, mas não apresentara o requerimento pertinente. Ao procurar um advogado, foi informado, corretamente, que:','{"A": "pode requerer a fruição do benefício, observado o prazo prescricional afeto à Fazenda Pública, pois, uma vez inserido no regime jurídico dos servidores, é vedada a supressão por lei posterior, sob pena de afronta ao direito adquirido;", "B": "não pode requerer a fruição do benefício, salvo se a Lei nº YY/2022 assegurou a sua fruição àqueles que não o tenham requerido em momento anterior, os quais tinham mera expectativa de direito;", "C": "não pode requerer a fruição do benefício, já que a pretensão administrativa deve ser apresentada de modo contemporâneo ao direito, pois um não pode subsistir dissociado do outro;", "D": "não pode requerer a fruição do benefício, já que a despesa pública está relacionada à previsão orçamentária, que não pode satisfazer benefícios relativos a exercícios pretéritos;", "E": "pode requerer a fruição do benefício, observado o prazo prescricional afeto à Fazenda Pública, pois tem o direito adquirido à sua fruição."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',27,'Direito Administrativo',null,'Laura, diretora de recursos humanos na Secretaria de Educação do Estado Alfa, foi informada de que três atos administrativos exarados em seu setor foram objeto de alteração: (1) o primeiro foi considerado, pela autoridade hierarquicamente superior, incompatível com o interesse público, o que a levou a substituí-lo por ato de teor diverso; (2) o segundo teve identificado um vício de finalidade, sendo determinada a cessação dos seus efeitos pela autoridade competente; e (3) o terceiro padecia de vício de competência, mas a autoridade competente aquiesceu com os seus termos, subscrevendo-o. Os acontecimentos descritos em 1, 2 e 3 refletem, respectivamente, os institutos da:','{"A": "anulação, revogação e retificação;", "B": "revogação, invalidação e convalidação;", "C": "invalidação, revogação e confirmação;", "D": "invalidação, contraposição e ratificação;", "E": "revogação, retificação e retirada hierárquica."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',28,'Direito Administrativo',null,'Determinada repartição pública estadual tinha em seu poder informações a respeito da filiação partidária de Joana, a qual fora declinada para fins de verificação da presença, ou não, de impedimento ao exercício de determinada função pública. Em razão das características desse dado, o responsável pela repartição consultou sua assessoria a respeito de sua natureza e sobre a possibilidade desse dado ser submetido a tratamento, com o objetivo de serem realizados estudos por órgão de pesquisa. A assessoria respondeu, corretamente, que se está perante dado:','{"A": "consentido, já que fornecido voluntariamente por Joana, o que afasta a necessidade de nova autorização para o respectivo tratamento;", "B": "pessoal sensível, não sendo necessário o fornecimento de consentimento do titular para tratamento, caso seja indispensável à realização da referida finalidade;", "C": "anonimizado, pois originário da relação funcional, tendo se incorporado à base de dados administrativa e não carecendo de consentimento do titular para a sua utilização;", "D": "público, pois originário da relação funcional, tendo se incorporado à base de dados administrativa e não carecendo de consentimento do titular para a sua utilização;", "E": "pessoal, sendo imprescindível o fornecimento de consentimento do titular para a realização de qualquer tratamento, inclusive para os fins descritos na narrativa."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',29,'Direito Administrativo',null,'Adalto, diretor de licitações no âmbito do Poder Executivo do Estado Alfa, recebeu comunicação de que esse ente federativo almejava realizar operação de crédito interno, havendo dúvida em relação à modalidade de procedimento licitatório a ser observado, considerando os balizamentos estabelecidos pela Lei nº 14.133/2021, que vinha sendo observada pela generalidade dos órgãos dessa estrutura de poder. À luz dessa narrativa, Adalto concluiu, corretamente, em razão do disposto na Lei nº 14.133/2021, que o contrato que verse sobre o referido objeto:','{"A": "não está sujeito ao regime do referido diploma normativo;", "B": "deve ser antecedido de licitação na modalidade de diálogo competitivo;", "C": "deve ser antecedido de licitação na modalidade de concorrência;", "D": "não precisa ser antecedido de licitação, que é dispensável, estando adstrito, apenas, aos balizamentos incidentes sobre o contrato administrativo;", "E": "não precisa ser antecedido de licitação, que é inexigível, estando adstrito, apenas, aos balizamentos incidentes sobre o contrato administrativo. Tipo 1 – Branca – Página 10"}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',30,'Direito Administrativo',null,'O Tribunal de Contas do Estado do Tocantins, em decisão transitada em julgado, rejeitou as contas apresentadas por João, ordenador de despesas no Município Alfa. Com isso, imputou-lhe um débito, além da aplicação de multa. Irresignado com a decisão, João consultou o seu advogado sobre a existência de alguma medida, a ser manejada no âmbito do próprio Tribunal, para que a decisão fosse alterada, já que, a seu ver, ocorrera um manifesto erro de cálculo nas contas. O advogado respondeu, corretamente, que:','{"A": "estavam exauridas as medidas passíveis de serem adotadas no âmbito do Tribunal de Contas;", "B": "pode ser proposta a ação de revisão, a ser manejada no biênio subsequente ao trânsito em julgado da decisão;", "C": "é cabível o pedido de reexame, a qualquer tempo, desde que baseado em perícia contábil, indicativa do erro de cálculo alvitrado por João;", "D": "é cabível a ação rescisória, a ser manejada nos cinco anos subsequentes ao trânsito em julgado da decisão, sendo facultada a produção de novas provas;", "E": "embora seja prevista a possibilidade de ser proposta ação rescisória contra decisões transitadas em julgado, ela só seria cabível em se tratando de falsidade de documentos."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',31,'Direito Administrativo',null,'O governador do Estado Alfa apresentou à Assembleia Legislativa o projeto de lei orçamentária anual. Após as discussões no âmbito da Comissão de Orçamento e Finanças, deliberou-se pela aprovação de diversas emendas individuais que buscavam viabilizar o desenvolvimento de determinada política pública. Apesar dessas emendas serem plenamente compatíveis com o plano plurianual e a lei de diretrizes orçamentárias, surgiram dúvidas em relação à origem dos recursos a serem utilizados. Após analisar as opções jurídica e politicamente viáveis, o presidente da Comissão observou, corretamente, que esses recursos poderiam resultar de anulação de despesas associadas:','{"A": "às dotações relativas à contribuição previdenciária;", "B": "às transferências voluntárias para os Municípios;", "C": "aos benefícios contínuos devidos aos servidores;", "D": "aos juros devidos em razão da dívida pública;", "E": "às transferências tributárias constitucionais."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',32,'Direito Administrativo',null,'O chefe do Poder Executivo do Estado Beta, em cujo território estava localizado o Município Alfa, almejava realizar uma transferência voluntária de recursos para esse ente federativo com o fim de viabilizar a realização de objetivos de interesse comum e amenizar os efeitos da grave crise financeira que assolava a municipalidade, cujo potencial turístico fora afetado por fortes chuvas. Ao analisar a arrecadação tributária do Município Alfa, que se mostrava elevada e supria suas despesas regulares, isto em momento anterior às fortes chuvas, a Procuradoria do Estado constatou que, por decisão das maiorias ocasionais, esse ente federativo não tinha instituído: (1) o imposto de transmissão inter vivos, a qualquer título, por ato oneroso, de bens imóveis; (2) nenhuma contribuição de melhoria, embora já tivesse realizado diversas obras públicas que poderiam justificá-la; e (3) a taxa associada ao recolhimento de lixo. Considerando a sistemática estabelecida pela Lei Complementar nº 101/2000, é correto afirmar que:','{"A": "a presença das situações descritas em 1, 2 e 3 é requisito indispensável à realização de transferências voluntárias pelo Estado Beta ao Município Alfa;", "B": "as situações descritas em 1, 2 e 3 acarretam, como consequência, a impossibilidade de ser realizada a transferência voluntária alvitrada;", "C": "apenas a situação descrita em 2 acarreta, como consequência, a impossibilidade de ser realizada a transferência voluntária alvitrada;", "D": "apenas a situação descrita em 1 acarreta, como consequência, a impossibilidade de ser realizada a transferência voluntária alvitrada;", "E": "as situações descritas em 1, 2 e 3 são projeções da autonomia política do Município Alfa, não constituindo óbice à realização de transferência voluntária pelo Estado Beta."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',33,'Direito Administrativo',null,'Em auditoria realizada pelo Tribunal de Contas do Estado do Tocantins, no âmbito de determinada estrutura estatal de poder, foi constatada a inexistência de comprovação de vultosas despesas realizadas na referida estrutura, sendo fortes os indícios de que os recursos públicos foram desviados e de que os atos ilícitos terão continuidade se o servidor público responsável pela estrutura não for cautelarmente afastado. O referido afastamento:','{"A": "pode ser promovido, em caráter temporário, pelo Tribunal de Contas, de ofício ou a requerimento do Ministério Público especial;", "B": "pode ser promovido, em caráter definitivo, pelo Tribunal de Contas, mas apenas se houver requerimento do Ministério Público especial;", "C": "não pode ser promovido, mesmo em caráter temporário, em momento anterior à decisão definitiva do Tribunal de Contas, o que decorre da presunção de inocência;", "D": "não pode ser promovido pelo Tribunal de Contas, apenas pelo Poder Judiciário, em caráter temporário, o que pressupõe requerimento do Ministério Público comum;", "E": "não pode ser promovido pelo Tribunal de Contas, apenas pelo Poder Judiciário, em caráter definitivo ou temporário, o que pressupõe requerimento do Ministério Público, especial ou comum. Tipo 1 – Branca – Página 11"}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',34,'Direito Administrativo',null,'Após amplos debates entre seus membros, o Tribunal de Justiça do Estado Alfa apresentou uma proposição à Assembleia Legislativa, veiculando o Estatuto da Magistratura do Estado Alfa. Ato contínuo, diversos parlamentares argumentaram com a inconstitucionalidade formal da respectiva proposição. O relator da matéria no âmbito da Comissão de Constituição e Justiça, após analisar os argumentos apresentados, concluiu, corretamente, que:','{"A": "a forma federativa de Estado autoriza que o Poder Judiciário de cada ente tenha o seu Estatuto, observados, sempre, os balizamentos estabelecidos pela Constituição da República de 1988;", "B": "a proposição somente será constitucional se tiver a forma de proposta de emenda constitucional, que observará os balizamentos estabelecidos pela Constituição da República de 1988;", "C": "o Estatuto da Magistratura tem sede exclusivamente constitucional, não sendo possível que a legislação infraconstitucional, federal ou estadual, trate da matéria;", "D": "a proposição somente será constitucional se tiver a forma de projeto de lei complementar, que complementará as normas estabelecidas pelo Estatuto Nacional da Magistratura;", "E": "a proposição é inconstitucional, já que a Constituição da República de 1988 somente dispõe sobre a existência do Estatuto Nacional da Magistratura."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',35,'Direito Administrativo',null,'Maria, servidora pública que, há cerca de dez anos, ocupava cargo de provimento efetivo no Estado do Tocantins, após regular aprovação em concurso público, tomou posse e entrou em exercício em cargo público diverso, vinculado ao mesmo ente federativo. Para sua decepção, foi inabilitada no estágio probatório relativo ao último cargo. Nesse caso, Maria deve ser:','{"A": "reintegrada ao cargo anterior, desde que este último esteja vago;", "B": "exonerada, cessando o seu vínculo funcional com o poder público;", "C": "readaptada ao cargo anterior, caso assim requeira, desde que este último esteja vago;", "D": "reconduzida ao cargo anterior e, se este último tiver sido provido, será aproveitada em outro;", "E": "revertida ao cargo anterior, ainda que este último esteja ocupado, o que pressupõe a prévia colocação em disponibilidade do respectivo ocupante. CONHECIMENTOS ESPECÍFICOS"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',36,'Língua Portuguesa',null,'Um teólogo inglês proferiu a seguinte frase: “O pessimista se queixa do vento, / o otimista espera que ele mude / e o realista ajusta as velas”. Sobre os componentes dessa frase, é correto afirmar que:','{"A": "o pessimista, o otimista e o realista mostram, diante de realidades diferentes, posicionamentos também diversos;", "B": "o pronome “ele” se refere, por coesão, ao termo “pessimista”, na frase anterior;", "C": "o segmento “ajusta as velas” traz sentido mais específico às frases anteriores;", "D": "os segmentos marcados nessa frase mostram perfeito paralelismo em sua organização sintática;", "E": "a conjunção E mostra sentido explicativo."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',37,'Língua Portuguesa',null,'Nas opções abaixo, apresentam-se paráfrases da frase anterior do teólogo inglês; a opção em que é seguida rigorosamente a mesma estruturação significativa da frase original, é:','{"A": "O pessimista se queixa da guerra, o otimista espera que ela termine e o realista prepara seus exércitos;", "B": "O pessimista se queixa dos preços dos alimentos, o otimista espera que eles caiam e o realista procura produtos substitutos;", "C": "O pessimista se queixa da demora do ônibus para o trabalho, o otimista espera que ele chegue rápido e o realista pensa em pegar um táxi;", "D": "O pessimista se queixa do vento forte, o otimista espera que ele perca a intensidade e o realista fecha a barraca na areia da praia;", "E": "O pessimista se queixa do preço da gasolina, o otimista espera que ele diminua e o realista decide abastecer com álcool."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',38,'Língua Portuguesa',null,'Um poeta romano escreveu: “Ninguém olha para o que há diante dos pés. Todos olham para as estrelas”. Considerando-se que se trata de um pensamento moralizante, o sentido da frase é o de que os homens:','{"A": "desprezam o presente em função de um futuro promissor;", "B": "não observam a realidade, preferindo os sonhos;", "C": "consideram os obstáculos da vida, mas preferem a poesia;", "D": "em lugar de pessimistas, procuram ser realistas;", "E": "encontram problemas na vida, mas os resolvem facilmente. Tipo 1 – Branca – Página 12"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',39,'Língua Portuguesa',null,'Numa fala de uma peça de teatro, um comediante holandês disse a seguinte frase: “É difícil encarar a realidade quando ela tem muitas faces”. A forma adequada de reescrever-se essa frase é:','{"A": "É difícil que encaremo-nos a realidade quando ela tem muitas faces;", "B": "É difícil que se encarasse a realidade quando ela tem muitas faces;", "C": "É difícil que a realidade seja encarada quando ela tem muitas faces;", "D": "É difícil a realidade ter sido encarada quando ela tem muitas faces;", "E": "É difícil que não se encare a realidade quando ela é multifacetada."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',40,'Língua Portuguesa',null,'A frase abaixo que NÃO mostra, como as demais, a possibilidade de diferentes pontos de vista, é:','{"A": "Nós todos vivemos sob o mesmo céu, mas não temos todos o mesmo horizonte;", "B": "O que a lagarta chama de fim do mundo, o mestre chama de borboleta;", "C": "O vento é o mesmo, mas sua resposta é diferente em cada folha;", "D": "É preciso aceitar que um dia você é o pombo e outros dias você é a estátua;", "E": "Se há uma opinião, fatos serão achados para apoiá-la."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',41,'Língua Portuguesa',null,'Há diferentes exemplos de intertextualidade. Todas as frases abaixo mostram intertextualidade; a opção em que é exemplificada uma alusão, é:','{"A": "Minha terra tinha palmeiras, mas já mataram todos os sabiás;", "B": "Já que todos devem trabalhar e meus netos vão ficar sozinhos, digam a todos eles que fico;", "C": "É o que dizia meu pai: “Problema que se resolve com dinheiro, não é problema”;", "D": "O lema da campanha já era conhecido: “Senta a pua!”;", "E": "A nova cozinheira fazia pratos horríveis, mas dizia como o famoso chefe francês “Marravilha!”."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',42,'Língua Portuguesa',null,'A frase abaixo cuja estruturação apela para a polissemia de um vocábulo, é:','{"A": "O sábio lê livros, mas também a vida;", "B": "Jornalismo consiste em comprar papel branco a dois centavos e vendê-lo a dez;", "C": "Bebendo-se um pouco de vinho, a inteligência aparece;", "D": "Quanto mais dividimos os obstáculos, mais fácil é vencê-los;", "E": "Champanhe: borbulhas espumantes, brancas como as pérolas de Cleópatra."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',43,'Língua Portuguesa',null,'Nos atos de comunicação, deve-se levar em conta a situação; a frase abaixo em que o significado do termo destacado depende da situação de comunicação, é:','{"A": "Amanhã começam as obras em nosso bairro;", "B": "Hoje, dia 15 de novembro, festeja-se a República;", "C": "Ainda se passeia muito pelas ruas do Rio;", "D": "Eles, o autor e o leitor, se merecem;", "E": "O quadro “O Dormitório” de Van Gogh é magnífico."}'::jsonb,'A',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',44,'Língua Portuguesa',null,'A frase abaixo que é modalizada no sentido de transmitir certeza absoluta, é:','{"A": "Fumar prejudica a saúde;", "B": "Certamente eles devem ter saído há pouco;", "C": "É claro que os maus alunos não conseguiram aprovação;", "D": "Os cidadãos urbanos respiram ar muito poluído;", "E": "A língua inglesa é predominante no Canadá."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',45,'Língua Portuguesa',null,'A frase abaixo que NÃO mostra nenhuma estrutura de caráter explicativo, é:','{"A": "Como fazer esse bolo? Seguindo a receita que está no livro;", "B": "Não é errado ter opiniões firmes. Errado é não ter nada além disso;", "C": "Os pesquisadores dos laboratórios Bell (Estados Unidos) inventaram o transistor, elemento de base dos computadores modernos;", "D": "Os garis são como as formigas: trabalham em conjunto e de forma organizada;", "E": "Todos querem viver muito tempo, mas ninguém quer ficar velho."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',46,'Língua Portuguesa',null,'O registro de um texto é constituído pelo conjunto de elementos expressivos que constroem um tom produtor de uma emoção particular no destinatário. Os principais registros são: o cômico, o satírico, o trágico, o lírico, o épico, o fantástico, o polêmico e o patético. A opção abaixo que exemplifica o registro satírico, é:','{"A": "Eis a sabedoria: gostar do vinho, da beleza e da primavera divina, isto é o bastante; o resto é futilidade;", "B": "Amor, dinheiro e lua, quando param de crescer, começam logo a diminuir;", "C": "Mais vale um galo no terreiro do que dois na testa;", "D": "Quem gosta de viver sozinho está sempre em má companhia;", "E": "Você não pode dizer quem está nadando nu até a maré baixar."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',47,'Língua Portuguesa',null,'Uma das características da textualidade é a coerência; a opção abaixo que mostra coerência, é:','{"A": "Um contrato verbal não vale o papel em que está escrito;", "B": "Quem tudo quer, tudo perde;", "C": "Nunca faça previsões, especialmente para o futuro;", "D": "O crítico de futebol está sempre certo porque só opina quando o jogo termina;", "E": "Não seja supersticioso – dá azar. Tipo 1 – Branca – Página 13"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',48,'Língua Portuguesa',null,'Observe o texto descritivo a seguir. “Em 1809, Dona Margarida, que não revelava a sua idade, tinha 75 anos. Conhecida em seu tempo como a bela quitandeira, ela era uma dessas raras mulheres que o tempo respeita, e devia a uma excelente constituição física o privilégio de manter uma beleza que, entretanto, não resistiria a um exame mais profundo.” A função da descrição nesse segmento é:','{"A": "documental, pois registra hábitos de uma época;", "B": "explicativa, pois justifica a psicologia do personagem;", "C": "metafórica, pois mostra uma outra realidade;", "D": "caracterizadora, pois estrutura um personagem;", "E": "argumentativa, pois defende um ponto de vista."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',49,'Língua Portuguesa',null,'Observe o segmento de narrativa a seguir. “Todos os passageiros corriam pela plataforma, pois o trem já havia chegado. Alguns já estavam instalados nos camarotes e observavam a confusão pela janela. Tenha juízo, meu filho. Telefone quando chegar. O trem apitou três vezes e começou lentamente a deslocar-se.” Esse segmento exemplifica uma maneira de inserir palavras numa narrativa, denominada:','{"A": "discurso indireto livre;", "B": "diálogo;", "C": "discurso indireto;", "D": "citação;", "E": "discurso direto."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',50,'Língua Portuguesa',null,'O segmento textual abaixo que deve ser classificado como argumentativo, é:','{"A": "Faça o que eu digo, mas não faça o que eu faço;", "B": "Viver é morrer aos poucos;", "C": "Numerosos são aqueles para quem a arte não passa de uma distração;", "D": "Como dizia o profeta, tudo na vida tem um fim e devemos preparar-nos para ele;", "E": "Os jovens costumam repetir o que dizem os pais e os professores."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',51,'Língua Portuguesa',null,'A opção abaixo que mostra um paradoxo, é:','{"A": "Eu admitiria facilmente que a paz pública é um grande bem; mas não posso esquecer que é por meio da ordem que os povos chegam à tirania;", "B": "O que foi seguido por todos, sempre e em todos os lugares, tem todas as chances de ser falso;", "C": "Atualmente, é muito comum que a maioria dos ciclistas das grandes provas estejam dopados;", "D": "Os atores cinematográficos certamente alcançam mais sucesso que os teatrais;", "E": "Os jornais impressos e televisivos fazem-nos viver os grandes acontecimentos mundiais."}'::jsonb,'B',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',52,'Língua Portuguesa',null,'A opção abaixo que exemplifica um raciocínio analógico, é:','{"A": "A Internet permite nossa comunicação rápida com muitas pessoas ao redor do mundo;", "B": "Choveu muito durante toda a madrugada; as ruas devem estar inundadas;", "C": "Da mesma forma que nos aprofundamos em ciências, devíamos aprofundar-nos em humanidades;", "D": "Depois dos 80, tudo nos lembra outra coisa;", "E": "Quem não levar dinheiro na carteira, que ponha mel nos lábios."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',53,'Língua Portuguesa',null,'Uma frase pode apresentar-se em formas variadas; a frase abaixo que apresenta uma forma enfática, colocando em destaque um de seus elementos, é:','{"A": "Eu não estarei presente amanhã na conferência;", "B": "Ainda existem muitas injustiças no mundo;", "C": "Teu pai é que vai ficar contente;", "D": "Os carros foram levados rapidamente;", "E": "Dois milhões de espectadores viram o filme."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',54,'Língua Portuguesa',null,'Todas as frases abaixo trazem as formas verbais no modo imperativo; a frase em que esse imperativo expressa um desejo, é:','{"A": "Fiquem quietos para as fotos!", "B": "Tragam-me o prisioneiro!", "C": "Mostre-me o seu desenho!", "D": "Não façam mais isso!", "E": "Pare de fumar!"}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',55,'Língua Portuguesa',null,'Todas as frases iniciais abaixo sofreram modificações; aquela opção em que a modificação transformou a frase para a forma impessoal, é:','{"A": "Comprei aquele carro ontem / Aquele carro foi comprado por mim ontem;", "B": "Não aceitamos esse julgamento parcial / Esse julgamento parcial, não o aceitamos;", "C": "Queremos transformar o mundo / Queremos a transformação do mundo;", "D": "Não desejamos nada alheio / Não se deseja nada alheio;", "E": "Não aprecio este tipo de música / Detesto este tipo de música. Tipo 1 – Branca – Página 14"}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',56,'Língua Portuguesa',null,'Observe a seguinte tese: O conflito de gerações é inicialmente a consequência de uma dificuldade de comunicação. Entre as opções abaixo, aquela que apresenta um exemplo, e não um argumento para a defesa dessa tese, é:','{"A": "Se os jovens e seus pais mostram às vezes dificuldades de comunicação, isso ocorre em função de uma diferença de educação;", "B": "Hoje, os jovens vivem em instabilidade referente a empregos, o que inquieta seus pais, habituados a uma vida mais estável;", "C": "Os vocábulos adotados pelos jovens são trazidos do inglês e constituem um dialeto no qual os jovens se reconhecem melhor do que as antigas gerações;", "D": "Se a comunicação é difícil entre as gerações, isso ocorre porque elas não falam a mesma língua;", "E": "Num romance francês, o jovem personagem e seu pai não se dão porque este último se recusa a aceitar a ideia do filho de não ser um carpinteiro como ele."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',57,'Língua Portuguesa',null,'Observe o texto a seguir. “O artista defendeu o direito de as pessoas seguirem a moda, mas reconhece que ela é muitas vezes ridícula pelos exageros que comete.” Trata-se de um texto argumentativo que emprega a seguinte estratégia:','{"A": "defesa da tese, levando em conta a força de uma tese oposta;", "B": "refutação de uma tese oposta, criticando os argumentos adversos;", "C": "debate da tese, mostrando paralelamente argumentos favoráveis e desfavoráveis;", "D": "afirmação de uma tese, reconhecendo aspectos positivos na tese contrária;", "E": "apresentação de argumentos de autoridade para a defesa de sua tese."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',58,'Língua Portuguesa',null,'O desenvolvimento de uma argumentação segue, na forma mais frequente, uma progressão coerente em direção a uma conclusão. Os componentes dessa progressão podem estar articulados por conectores. As opções abaixo mostram o tipo de relação lógica entre os componentes, assim como conectores adequados para a expressão dessa relação. A opção em que a relação lógica é seguida de pelo menos um conector inadequado, é:','{"A": "relação de adição: além disso, não só... mas também;", "B": "relação de oposição: todavia, no entretanto;", "C": "relação de comparação: do mesmo modo, assim como;", "D": "relação de concessão: ainda que, conquanto;", "E": "relação de conclusão: logo, portanto."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',59,'Língua Portuguesa',null,'A frase abaixo foi redigida sem a pontuação original: “Amigo é aquele que sabe tudo a seu respeito e mesmo assim ainda gosta de você”. A forma de reescrever essa frase com a sua pontuação adequada, é:','{"A": "Amigo é aquele, que sabe tudo a seu respeito, e mesmo assim, ainda gosta de você.", "B": "Amigo é aquele, que sabe tudo a seu respeito, e, mesmo assim, ainda gosta de você.", "C": "Amigo é aquele que sabe tudo a seu respeito, e, mesmo assim, ainda gosta de você.", "D": "Amigo é aquele, que sabe tudo a seu respeito, e, mesmo assim ainda gosta de você.", "E": "Amigo é aquele que sabe tudo a seu respeito, e mesmo assim, ainda gosta de você."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',60,'Língua Portuguesa',null,'Em todas as frases abaixo há uma imprecisão nos dados numéricos, EXCETO em uma; a opção em que não há imprecisão, é:','{"A": "Havia na palestra cerca de 200 assistentes;", "B": "Minha ex-namorada já tem seus 60 anos;", "C": "O Brasil tem perto de 200 milhões de habitantes;", "D": "O Havaí tem mais de 50 vulcões;", "E": "Sua certidão registra 70 anos de vida."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',61,'Língua Portuguesa',null,'Uma das principais características do texto informativo é a sua clareza; um dos meios para conseguir clareza é a utilização da ordem direta nas frases. A frase abaixo que está na ordem direta, é:','{"A": "O Natal é a época em que as pessoas ficam sem dinheiro;", "B": "Com os amigos que tenho, não preciso de inimigos;", "C": "É impossível ensinar um gato a não pegar passarinhos;", "D": "Antes um pássaro a voar que dois na mão;", "E": "Pisado, o menor verme se revira."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',62,'Língua Portuguesa',null,'Como os textos informativos se preocupam bastante com a clareza, alguns deles traduzem as siglas neles contidas entre parênteses. A opção abaixo em que essa “tradução” está correta, é:','{"A": "O MST (Movimento dos Sem-Trabalho) exige reformas na legislação trabalhista;", "B": "O inquilino jurou pagar o IPTU (Imposto Predial e Territorial Urbano) até o final do mês;", "C": "O chefe do FMI (Fundação Mundial de Intercâmbio) visitará o país ainda este ano;", "D": "A Rússia ficou preocupada com a filiação da Ucrânia à OTAN (Organização do Tratado Americano das Nações);", "E": "A ONU (Organização das Nações Unificadas) condenou a guerra. Tipo 1 – Branca – Página 15"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',63,'Língua Portuguesa',null,'Aedes aegypti é uma forma latina que designa o mosquito causador da dengue (“mosquito do Egito”). O latinismo cujo significado está corretamente indicado, entre as opções abaixo, é:','{"A": "Em época de crise, o lazer fica adiado sine die / para uma data já marcada;", "B": "Para um debate é importante ter a priori algumas informações / de forma privilegiada;", "C": "O esgoto in natura é jogado em local distante / sem tratamento;", "D": "Algumas populações respeitam seu habitat / o modelo habitacional;", "E": "Não houve quorum suficiente para a votação do projeto / debate público."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',64,'Língua Portuguesa',null,'“O policial olha pela janela a menina correndo, alguns homens que a perseguiam e pessoas em fuga.” Se o autor da frase tivesse preocupação com o paralelismo na construção dessa frase, sua forma seria:','{"A": "O policial olha pela janela a menina correndo, alguns homens perseguindo-a e pessoas fugindo;", "B": "O policial olha pela janela a menina que corria, alguns homens que a perseguiam e pessoas em fuga;", "C": "O policial olha pela janela a menina em corrida, alguns homens que a perseguiam e pessoas em fuga;", "D": "O policial olha pela janela a menina correndo, alguns homens que a perseguiam e pessoas fugindo;", "E": "O policial olha pela janela a menina correndo, alguns homens que a perseguiam e pessoas que fugiam."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',65,'Língua Portuguesa',null,'Os slogans publicitários sempre se apoiam em alguns valores sociais para o sucesso de venda dos produtos anunciados. O slogan abaixo cujo valor social está corretamente identificado, é:','{"A": "Hortifrúti: a natureza a seu alcance / defesa do meio ambiente;", "B": "Faça suas compras aqui, uma loja de seu bairro / intimidade;", "C": "As impressoras FACIT imprimem mais rápido / economia;", "D": "Compre Chevrolet e se sinta nas nuvens / beleza;", "E": "Use agendas Ediouro / organização pessoal."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',66,'Língua Portuguesa',null,'Observe o texto narrativo a seguir. “Devo suspender momentaneamente a narrativa para explicar o título dado a esse romance, algo que já deveria ter sido feito.” Nesse caso, a interrupção da narrativa deve ser classificada como:','{"A": "interpelação direta ao leitor;", "B": "referência ao já conhecido por autor e leitor;", "C": "utilização de travessões ou parênteses;", "D": "comentário sobre processos de narração;", "E": "mudança de gênero textual."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',67,'Língua Portuguesa',null,'Todos sabemos que o texto descritivo utiliza muitas formas de adjetivação; entre as opções abaixo, aquela que tem a forma de adjetivação corretamente identificada, é:','{"A": "Van Gogh era o pintor! / adjetivo;", "B": "Os alunos que estudam têm chance de sucesso / oração adjetiva;", "C": "Morava num casebre no final da rua / comparação;", "D": "Ele não escreveu uma história parecida? / forma reduzida;", "E": "Havia no ar um perfume masculino / afixos."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',68,'Língua Portuguesa',null,'“O professor olhou o livro de capa grossa e colorida sobre a mesa, pegou-o, virou-o ao contrário e pôde observar a mesma cor na contracapa.” Sobre essa pequena descrição, é correto afirmar que:','{"A": "o observador e o objeto descrito estão imóveis;", "B": "o observador está em movimento e o objeto descrito, imóvel;", "C": "os dados descritivos são de base visual e tátil;", "D": "o observador e o objeto descrito estão em movimento;", "E": "o observador está imóvel e o objeto descrito, em movimento."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',69,'Língua Portuguesa',null,'O ato de descrever sofre uma série de limitações; no texto a seguir, por exemplo, o observador não pôde descrever com exatidão o animal que via. “O menino entrou no Zoológico, soltou-se da mão da mãe, e logo na primeira jaula viu um animal estranho: aproximou-se da grade e viu que ele possuía patas grandes e fortes na traseira, mas patas menores na parte dianteira ou superior e uma espécie de corte no pelo, na altura da barriga, onde havia um filhote”. Nesse caso, a descrição incompleta se deve:','{"A": "a limitações da visão do observador;", "B": "ao distanciamento entre o observador e o animal;", "C": "à falta de conhecimento do observador;", "D": "a problemas psicológicos do observador;", "E": "ao fato de o objeto ser um espécime único no mundo."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Analista Técnico – Letras',2022,null,'Tipo 1',70,'Língua Portuguesa',null,'“Existem dois lados em cada problema: o nosso lado e o lado muito errado.” Nessa frase há uma forma de superlativo (muito errado); a frase abaixo em que NÃO há qualquer forma de superlativo, é:','{"A": "É bem difícil conviver com um pessimista;", "B": "O otimismo exagerado é um defeito chatinho;", "C": "Fatos são coisas teimosas pra burro;", "D": "Os legumes estão baratos;", "E": "O homem estava algo abatido devido à doença. Tipo 1 – Branca – Página 16 DISCURSIVA 1 Transforme as frases verbais abaixo em frases nominais a fim de formar títulos para reportagens de jornais impressos: a) A classe política declarou-se satisfeita depois da publicação do calendário eleitoral. b) O Congresso, após o período de recesso, retomou suas atividades. c) Espera-se um debate acalorado entre candidatos à presidência. d) Canais de TV fixam datas para apresentarem a nova programação. Valor: 15 pontos Máximo de 15 linhas. 2 Em cada uma das frases abaixo, elimine as marcas de enunciação de modo a produzir frases adequadas aos tipos solicitados entre parênteses. a) Deveríamos incentivar o ensino musical entre alunos do ensino médio. (tipo de frase na voz passiva com auxiliar) b) Eu desconfio de todos esses produtos da indústria agroalimentar. (tipo injuntivo de frase) c) Lastimamos não ser mais ampla a solidariedade entre os povos. (tipo impessoal de frase) d) Esperam os cientistas serem eficientes as vacinas contra a varíola dos macacos. (tipo enfático, com a valorização de um termo) Valor: 15 pontos Máximo de 15 linhas. Tipo 1 – Branca – Página 17 RASCUNHO - Prova Discursiva - Questão 1 1 5 10 15 RASCUNHO - Prova Discursiva - Questão 2 1 5 10 15"}'::jsonb,'D',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/analista_tecnico_-_letrasanaletras_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','alternativa muito longa: pode conter texto de outra questão; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno')
insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',1,'Língua Portuguesa',null,'Em cada texto a seguir, retirado do jornal O Globo, ocorrem processos de dar precisão e segurança ao que se transmite; a opção em que NÃO há marcas dessa estratégia é:','{"A": "“O Surfe: historiador revela como o ritual religioso dos antigos polinésios virou esporte nos EUA”;", "B": "“O ensino atual de literatura está afastando os jovens dos livros, alerta o influente crítico francês Tzvetan Todorov”;", "C": "“O acidente com a carreta numa estrada de Minas causou a morte de cerca de 10 pessoas e parece ter sido causado por imperícia do motorista”;", "D": "“Após dois adiamentos e um repasse de R$ 25 bilhões do caixa do BNDES, a Petrobrás anunciou que investirá US$ 174 bi até 2013. O volume é 55% maior do que o registrado no programa anterior”;", "E": "“Um mês antes do Carnaval, a ocupação dos hotéis cariocas já chega a 77%, segundo a Associação Brasileira da Indústria de Hotéis do Rio. Apesar da crise, os números são melhores que os de 2008, quando a taxa de ocupação era de 67% nesse mesmo período”."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',2,'Língua Portuguesa',null,'Entre os diversos tipos de frases há as interrogativas e, entre essas, há aquelas que são chamadas de interrogações retóricas; a pergunta retórica abaixo cuja resposta está contida na pergunta é:','{"A": "Você pode fechar a janela, por favor?", "B": "Esse político está falando a verdade?", "C": "O senhor poderia falar mais alto?", "D": "Eu já não tinha dito isso?", "E": "Quem nunca sentiu medo?"}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',3,'Língua Portuguesa',null,'Abaixo estão frases retiradas de jornais diversos; de cada uma dessas frases foi indicada uma inferência. A frase em que a inferência é adequada é:','{"A": "Em função das chuvas, os rios amazonenses inundaram suas margens / A pesca nos rios amazonenses vai ser mais farta;", "B": "O time do Flamengo comprou mais um jogador / O Flamengo vai ganhar o campeonato brasileiro;", "C": "As férias escolares acabam no próximo domingo, no Rio / O trânsito vai começar a ficar mais difícil no Rio;", "D": "Para treinamento, escoteiros dirigiram o trânsito no centro de Belo Horizonte / Os policiais estão em greve;", "E": "O Carnaval este ano foi menos violento / Poucos turistas vieram para o Carnaval."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',4,'Língua Portuguesa',null,'Uma das formas mais simples de argumentar consiste de duas frases, uma das quais é a conclusão da outra, chamada premissa. A opção abaixo em que a ordem das frases é a de conclusão (C) seguida da premissa (P) é:','{"A": "O leite está transbordando da leiteira / O leite deve ter fervido;", "B": "É possível que Pedro seja eleito senador / Pedro tem muitos eleitores no interior do Estado;", "C": "Meu primo está bem empregado / Meu primo acaba de comprar um carro luxuoso;", "D": "A guerra Rússia x Ucrânia registrou novos combates ontem / A Rússia deve estar enfrentando dificuldades econômicas;", "E": "Minha mulher nunca sofreu um acidente com o carro / Minha mulher é boa motorista."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',5,'Língua Portuguesa',null,'Sempre que, num raciocínio, passamos de uma premissa a uma conclusão (ou vice-versa), assumimos como verdadeira uma ideia intermediária. Essa ideia intermediária está corretamente indicada na seguinte opção:','{"A": "A esposa foi vista pelo irmão dele no cinema, com outro; ele vai separar-se / O irmão dele diz a verdade;", "B": "As pesquisas eleitorais indicam a vitória de Putin; os russos estão perdidos / As pesquisas mostram interesses políticos;", "C": "É conveniente estacionar o carro; há um barulho na traseira / Foram comprados pneus recauchutados;", "D": "Fiz o exercício e encontrei a mesma resposta do professor; acertei mais esse / O professor nem sempre acerta;", "E": "Meu celular despertou; tenho que levantar rápido / Meu gerente é muito exigente quanto a horário."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',6,'Língua Portuguesa',null,'Em algumas frases, os seus autores jogaram com o significado polissêmico de palavras; a opção em que essa estratégia foi empregada é:','{"A": "Os espelhos fariam muito bem em refletir um pouco antes de mostrar as imagens;", "B": "Saudade é a presença da ausência;", "C": "Originalidade não consiste apenas em fazer as coisas de forma diferente, mas também em fazê-las melhor;", "D": "Há três maneiras de fazer as coisas: a maneira errada, a maneira certa e uma maneira melhor;", "E": "Eu quase nada sei, mas desconfio de muita coisa."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',7,'Língua Portuguesa',null,'Observe agora o raciocínio a seguir. 1. Uma pesquisa mostra que os camelôs vendem mais barato; 2. A presença de camelôs na rua é conveniente. Esse raciocínio pode ser refutado porque:','{"A": "a premissa não é geralmente verdadeira;", "B": "a conclusão nada tem a ver com a premissa;", "C": "a conclusão deixa de considerar outros fatores;", "D": "a premissa se apoia em dados falsos;", "E": "a premissa e a conclusão não mostram relação lógica. Tipo 1 – Branca – Página 4"}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',8,'Língua Portuguesa',null,'Considerando que as premissas de um raciocínio podem ser fatos, julgamentos, testemunhos de autoridade ou exemplos, a opção em que a premissa deve ser classificada como julgamento é:','{"A": "Como o estudo da Prefeitura comprovou o perigo de morar nessa encosta, devemos fazer a transferência dos moradores;", "B": "Como o Ibope mostrou a vitória do candidato X, é perda de tempo votar em Y;", "C": "Muitos acidentes ocorrem nesse cruzamento, por isso é urgente o conserto do sinal de trânsito;", "D": "É mais interessante fazer turismo no Nordeste que na Europa, pois devemos ser mais patriotas em nossos gastos;", "E": "Pedro não se deu bem na prova do concurso, por isso devemos estudar muito mais."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',9,'Língua Portuguesa',null,'Abaixo estão frases com raciocínios indutivos; a opção em que a conclusão apontada é fruto de uma generalização é:','{"A": "O computador do TSE tem alta capacidade de contabilização, por isso deve encerrar as eleições em pouco tempo;", "B": "O livro sobre citações de autores célebres é grosso e bem encadernado, além de caro, por isso não deve vender muito;", "C": "Um cachorro salvou a vida de seu dono, avisando-o sobre o risco de desabamento da casa; vou providenciar a adoção de um cachorro para cá;", "D": "Na escola de meu filho mediram a altura de meninos e meninas e chegaram à conclusão de que as mulheres estão crescendo mais do que os homens;", "E": "Os táxis passaram a adotar a política dos supermercados, ou seja, oferecendo preços mais baratos e aumentando o número de clientes, o que se mostrou uma política de sucesso."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',10,'Língua Portuguesa',null,'A frase abaixo que mostra um raciocínio falso, classificado como círculo vicioso, é:','{"A": "Ayrton Senna foi, sem dúvida, o melhor corredor brasileiro de todos os tempos, pois nenhum outro conseguiu igualar-se a ele;", "B": "Todos os nossos problemas desapareceriam se aumentássemos o tamanho da casa onde moramos;", "C": "Não é conveniente para a Prefeitura cancelar esse próximo feriado, pois os cariocas gostam muito de praia;", "D": "Não acredito que você esteja lembrando-me esses fatos; a mim, que sou historiador;", "E": "Estatísticas mostram que mais de 80% dos eleitores preferem votar em pessoas mais velhas, o que favorece os idosos nas próximas eleições."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',11,'Língua Portuguesa',null,'Entre os raciocínios abaixo, aquele que mostra uma falha por apoiar-se numa falsa analogia, é:','{"A": "Os médicos são profissionais diferentes, pois parecem não preocupar-se demais com os seus ganhos;", "B": "O novo atacante do Grêmio deve ser ótimo jogador, pois seu pai chegou a jogar na seleção;", "C": "Os franceses são delicados cozinheiros e os alemães, disciplinados guerreiros, por isso não se entendem;", "D": "A melhor universidade do país é a USP, pois é a que apresenta melhores condições de ensino;", "E": "Se quisermos melhorar o aprendizado da Matemática, basta adotarem-se livros importados."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',12,'Língua Portuguesa',null,'Numa delegacia, uma mulher foi queixar-se do marido, que havia ido embora de casa. No depoimento, fez uma série de frases com vocábulos de conteúdo semântico negativo para trazer mais condenação ao marido. A frase abaixo em que o termo sublinhado NÃO tem conotação negativa é:','{"A": "Meu marido me abandonou na última sexta-feira;", "B": "Ele rabiscou algumas explicações;", "C": "As explicações foram dadas numa folha de papel;", "D": "Ele lambuzou o verso da folha e grudou-a na mesa;", "E": "Foi embora e largou até a porta aberta."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',13,'Língua Portuguesa',null,'Na escrita, ocorrem alguns processos de manipulação da realidade, como a reificação (tratamento de coisa dado ao homem) e a personalização, que dá características humanas a coisas ou animais. A opção abaixo que exemplifica uma personalização é:','{"A": "Seus sonhos se transformaram em pó;", "B": "O mar de Copacabana já matou muitas crianças;", "C": "A morte sai mais barata que a vida;", "D": "Os imigrantes foram depositados num galpão;", "E": "Os prisioneiros vieram empilhados num trem de carga."}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',14,'Língua Portuguesa',null,'Em todas as opções abaixo há uma frase que foi reescrita de modo a destacar-se um dos seus elementos; a opção em que essa reescritura foi feita de forma gramaticalmente inadequada, é:','{"A": "Eu trouxe a encomenda para meu irmão / A encomenda, eu lhe dei a meu irmão;", "B": "O gerente entregou a chave ao porteiro / Ao porteiro, o gerente lhe entregou a chave;", "C": "O jogador xingou a torcida ao sair de campo / Ao sair de campo, o jogador xingou a torcida;", "D": "Nunca mais vi meu pai / Ver meu pai, nunca mais;", "E": "Observei a camisa na vitrine / A camisa, eu a observei na vitrine."}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',15,'Língua Portuguesa',null,'Observe a seguir o início de um texto. “’Há muita gente complicando a vida do prefeito, inclusive o próprio prefeito’, costuma dizer um vereador. Trata-se de uma revelação de caráter generalizado na Câmara.” A introdução desse texto deve ser identificada como:','{"A": "alusão histórica;", "B": "interrogação;", "C": "suspense;", "D": "convite;", "E": "citação. Tipo 1 – Branca – Página 5 Legislação Específica"}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',16,'Direito Administrativo',null,'Joana, servidora estável ocupante de cargo de provimento efetivo em uma estrutura de poder do Estado do Tocantins, sofreu limitação em sua capacidade mental, devidamente comprovada, no período em que estava em exercício funcional, o que a impossibilitou de exercer as funções afetas ao cargo para o qual fora aprovada em concurso público. Nesse caso, à luz da normatização vigente, Joana deve ser:','{"A": "imediatamente readaptada, sendo investida em cargo de atribuições e responsabilidades compatíveis com sua limitação;", "B": "aposentada por invalidez, ainda que esteja apta a exercer as funções afetas a cargo de atribuições e responsabilidades compatíveis com sua limitação;", "C": "aproveitada em funções compatíveis com as limitações que tenha sofrido em sua capacidade mental, remanejada no subsequente e, passado mais um ano, readaptada;", "D": "remanejada em funções compatíveis com as limitações que tenha sofrido em sua capacidade mental, podendo ser readaptada após dois anos, observados os requisitos legais;", "E": "imediatamente readaptada, sendo investida em cargo de atribuições e responsabilidades compatíveis com sua limitação e, ato contínuo, aproveitada para funções diversas."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',17,'Direito Administrativo',null,'A autarquia Alfa, vinculada a ente federativo submetido à atuação do Tribunal de Contas do Estado do Tocantins, veio a ser extinta em razão da reconhecida ineficiência dos resultados que vinha alcançando. Nesse caso, esse ente da administração pública indireta:','{"A": "não está sujeito à fiscalização do Tribunal de Contas;", "B": "está sujeito à fiscalização do Tribunal de Contas e deve ser apresentada a prestação de contas extraordinária, por ocasião de sua extinção;", "C": "está sujeito à fiscalização do Tribunal de Contas e as respectivas contas devem ser anexadas às contas anuais do ente federativo a que estava vinculado;", "D": "não está sujeito à fiscalização do Tribunal de Contas, mas sua extinção pode gerar reflexos no ente federativo ao qual está vinculado, o que exige a tomada de contas especial;", "E": "somente estará sujeito à fiscalização do Tribunal de Contas, em sede de prestação de contas regular, caso tenha recebido aportes do Tesouro no exercício financeiro de sua extinção."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',18,'Direito Administrativo',null,'Em razão do cargo que ocupa em determinado ente federativo, o qual está submetido à atuação do Tribunal de Contas do Estado do Tocantins, João recebeu determinado numerário para a realização de despesas, de pequeno valor, que não podiam se submeter ao processo ordinário ou comum. Nesse caso, João deve prestar contas:','{"A": "ao Tribunal de Contas, o que ocorrerá a partir de formulário específico, fornecido pelo órgão de controle interno, ao qual serão anexados os documentos comprobatórios das despesas realizadas;", "B": "à autoridade que lhe seja superior, cabendo aos órgãos de controle interno encaminhá-las ao Tribunal de Contas, mensalmente, juntamente com as demais prestações de natureza similar;", "C": "à autoridade que lhe seja superior, cabendo aos órgãos de controle interno encaminhá-las ao Tribunal de Contas, anualmente, juntamente com as demais prestações de natureza similar;", "D": "à autoridade que lhe seja superior, sendo que os órgãos de controle interno submeterão ao Tribunal de Contas apenas aquelas que contiverem irregularidades insanáveis pela própria administração;", "E": "ao Tribunal de Contas, observados os prazos a serem respeitados pelos demais ordenadores de despesas, com a peculiaridade de que as contas serão simplificadas, desacompanhadas de documentos."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',19,'Direito Administrativo',null,'Maria, servidora do Tribunal de Contas do Estado do Tocantins, foi informada por um colega de setor que vinha sendo cogitada a sua designação para atuar na Comissão de Ética. A notícia deixou Maria surpresa, pois, apesar de atuar há uma década no Tribunal, era ocupante de cargo em comissão. Além disso, estava respondendo a um processo disciplinar por ter atuado em processo administrativo de interesse do seu irmão. À luz dessa narrativa, Maria:','{"A": "pode ser designada, em razão da isonomia entre todos os servidores e do princípio da presunção de inocência;", "B": "pode ser designada, pois apenas é exigido que o servidor tenha mais de três anos de carreira e que não tenha sido condenado em processo disciplinar;", "C": "não pode ser designada, mas apenas por ser ocupante de cargo em comissão, não por estar respondendo a processo disciplinar, isto em razão da presunção de inocência;", "D": "não pode ser designada, por ser ocupante de cargo em comissão, acrescendo-se que o fato de estar respondendo a processo disciplinar obstaria o exercício das funções;", "E": "não pode ser designada, mas apenas por estar respondendo a processo disciplinar, não por ser ocupante de cargo em comissão, pois não há distinções entre os servidores. Tipo 1 – Branca – Página 6"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',20,'Direito Administrativo',null,'Joana tomou posse no cargo de auditor de controle externo do Tribunal de Contas do Estado do Tocantins. Durante o seu desenvolvimento funcional, (1) passou para o padrão de vencimento imediatamente superior, isto dentro da mesma classe, observado o interstício mínimo previsto em lei, (2) continuou passando para os padrões subsequentes, dentro da mesma classe, até alcançar o último padrão; e (3) após o interstício de dois anos de efetivo exercício no último padrão da classe, passou para o primeiro padrão da classe imediatamente superior. À luz da narrativa, as situações 1, 2 e 3 descrevem, respectivamente:','{"A": "promoção, progressão e transposição;", "B": "promoção, promoção e transposição;", "C": "progressão, progressão e promoção;", "D": "progressão, avanço e promoção;", "E": "avanço, avanço e progressão. Controle Externo"}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',21,'Direito Administrativo',null,'Maria, após cumprir os requisitos exigidos, teve deferida a sua aposentadoria voluntária por tempo de serviço, sendo o respectivo expediente encaminhado ao Tribunal de Contas do Estado Alfa para fins de registro. Os autos ingressaram no Tribunal em dezembro de 2015 e somente no último mês foi designada a sessão de julgamento na qual seria apreciada a legalidade do ato. À luz da sistemática constitucional, é correto afirmar que:','{"A": "por se tratar de ato de concessão inicial de aposentadoria, não é necessário que Maria seja ouvida, tendo o Tribunal a possibilidade de realizar ampla cognição sobre o ato;", "B": "em razão dos princípios da segurança jurídica e da confiança legítima, o ato de aposentadoria deve ser considerado definitivamente registrado;", "C": "em razão do decurso do tempo, a cognição do ato de aposentadoria pelo Tribunal somente será possível caso haja impugnação de terceiros;", "D": "o Tribunal somente poderá alterar o título de aposentadoria se o respectivo ato contiver vício insanável, não convalidável pelo decurso do tempo;", "E": "embora se trate de ato de concessão inicial de aposentadoria, deve ser assegurado o contraditório e a ampla defesa a Maria."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',22,'Direito Administrativo',null,'O Tribunal de Contas do Estado Beta recebeu, para análise, as contas de governo do prefeito do Município Alfa. Considerando os balizamentos estabelecidos pela Constituição da República de 1988, a referida análise deve:','{"A": "realizar amplo juízo valorativo a respeito das contas, podendo aplicar multa e imputar os débitos que sejam identificados, sem prejuízo do julgamento político a cargo da Câmara Municipal de Alfa, que só rejeitará o parecer por maioria qualificada;", "B": "se restringir à emissão de parecer prévio, que só deixará de prevalecer por maioria qualificada de votos da Câmara Municipal de Alfa, sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo;", "C": "se restringir à emissão de parecer prévio, que só deixará de prevalecer por maioria qualificada de votos da Câmara Municipal de Alfa, não sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo;", "D": "julgar as contas, realizando amplo juízo valorativo a respeito das informações apresentadas, sendo que a sua decisão somente deixará de prevalecer pelo voto de dois terços dos membros da Câmara Municipal de Alfa;", "E": "se restringir à emissão de parecer prévio, que só deixará de prevalecer pela unanimidade dos votos da Câmara Municipal de Alfa, sendo cabível o julgamento ficto das contas, por este órgão, pelo decurso do tempo."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',23,'Direito Administrativo',null,'João, servidor público ocupante de cargo de provimento efetivo, que atuara como ordenador de despesas no Município Alfa, foi condenado em processo administrativo, no âmbito do Tribunal de Contas do Estado do Tocantins, pela prática de infração considerada grave. Nesse caso, João:','{"A": "somente pode ser condenado à sanção de multa, além de ter a obrigação de ressarcir os danos que tenha causado ao erário;", "B": "deve ser sempre condenado à sanção de multa, além de ser considerado em débito, se for o caso, ficando ainda inabilitado, nos termos da lei, para o exercício de cargo em comissão ou função de confiança;", "C": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inabilitado, por decisão tomada por maioria absoluta, nos termos da lei, para exercer cargo em comissão ou função de confiança;", "D": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inelegível, por decisão tomada por maioria absoluta, nos termos da lei, para exercer cargo eletivo estadual;", "E": "pode ser condenado à sanção de multa, além de ser considerado em débito, se for o caso, e ainda ficar inelegível, por decisão tomada por maioria de dois terços, nos termos da lei, para exercer qualquer cargo eletivo. Tipo 1 – Branca – Página 7"}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',24,'Direito Administrativo',null,'João, recém-empossado como servidor do Tribunal de Justiça do Estado Alfa, decidiu se inteirar a respeito das linhas de defesa a que estarão sujeitas as contratações públicas, conforme dispõe a Lei nº 14.133/2021. Ao final, concluiu que o controle interno integra a segunda linha de defesa e o Tribunal de Contas figura, isolado, na terceira linha de defesa. À luz do que dispõe o referido diploma normativo, é correto afirmar que a conclusão de João está:','{"A": "errada, pois as linhas de defesa não se apresentam de modo sequencial, mas simultâneo, congregando todos os agentes públicos, as unidades de assessoramento jurídico, o controle interno, o Tribunal de Contas e o Poder Judiciário;", "B": "certa, pois a generalidade dos órgãos de controle interno integra a segunda linha, enquanto o Tribunal de Contas ocupa a última linha de defesa administrativa, imediatamente anterior ao controle jurisdicional;", "C": "certa, ressaltando-se que a última linha de defesa é móvel, de modo que o Tribunal de Contas ali se encontra, de forma isolada, enquanto a questão não é judicializada;", "D": "errada, pois o Tribunal de Contas não integra, isolado, a terceira linha de defesa, estando acompanhado do órgão central de controle interno da Administração;", "E": "errada, pois a generalidade dos órgãos de controle interno não integra a segunda linha, mas, sim, a terceira linha, juntamente com o Tribunal de Contas."}'::jsonb,'D',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',25,'Direito Administrativo',null,'Em determinado contrato administrativo, foi constatado, pelo órgão de controle interno do Município Alfa, a ocorrência de irregularidade insanável no procedimento licitatório que lhe deu origem. Nesse caso, à luz da sistemática estabelecida na Lei nº 14.133/2021, a declaração de nulidade do contrato administrativo:','{"A": "é medida que se opera imediatamente, de pleno direito, apresentando contornos meramente declaratórios, não constitutivos;", "B": "afasta, em qualquer caso, o dever de a Administração indenizar o contratado pelo que houver executado até a data em que for declarada;", "C": "independe de qualquer avaliação complementar pela autoridade administrativa, devendo ser declarada nos cinco dias subsequentes ao conhecimento dos fatos;", "D": "pode vir a produzir efeitos apenas no futuro, observados os limites temporais estabelecidos em lei, para fins de nova contratação, de modo a assegurar a continuidade da atividade administrativa;", "E": "não exige a avaliação dos aspectos circunstanciais e das consequências do ato, o que será feito apenas para fins de dimensionamento da indenização do contratado, que não pode ter concorrido para a nulidade. CONHECIMENTOS ESPECÍFICOS"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',26,'Direito Administrativo',null,'João, prefeito do Município Beta, logo após ser reeleito para o segundo mandato consecutivo à frente do Poder Executivo desse ente federativo, se reuniu com sua equipe com o objetivo de traçar a estratégia a ser adotada para a eleição subsequente. Afinal, o seu crescente prestígio lhe dava esperança de continuar a exercer a representatividade popular. Ao consultar os seus assessores a respeito da possibilidade de ser eleito para um novo mandato, foi-lhe corretamente respondido que a ordem constitucional somente permite:','{"A": "duas reeleições para a chefia do Poder Executivo, logo, João poderia concorrer ao cargo de prefeito do Município Beta na próxima eleição;", "B": "uma reeleição para a chefia do Poder Executivo, de modo que João não poderia concorrer a nenhum cargo eletivo dessa natureza, qualquer que fosse o ente e o nível federativo;", "C": "uma reeleição para cargo, da mesma natureza, de chefe do Poder Executivo, de modo que João apenas não poderia concorrer, na próxima eleição, ao cargo de prefeito municipal, ainda que em Município diverso;", "D": "uma reeleição, no mesmo Município, para a chefia do Poder Executivo, mas João pode concorrer ao cargo de prefeito municipal em Município diverso;", "E": "uma reeleição para a chefia do Poder Executivo, estando o respectivo agente inelegível para qualquer cargo eletivo na eleição subsequente."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',27,'Direito Administrativo',null,'O governador do Estado Alfa foi cientificado de que o Município Beta, situado em seu território, não pagava, há três anos, a dívida decorrente de contratos de financiamento com instituições financeiras governamentais, que tinham por objetivo viabilizar a realização de obras públicas. A ausência de pagamento não decorria de força maior, mas, sim, de opção política do prefeito municipal. Considerando a narrativa, essa espécie de dívida é considerada:','{"A": "flutuante e pode ensejar a decretação da intervenção espontânea;", "B": "fundada e pode ensejar a decretação da intervenção espontânea;", "C": "fundada e somente pode ensejar a decretação da intervenção provocada;", "D": "flutuante e somente pode ensejar a decretação da intervenção provocada;", "E": "mobiliária e somente pode ensejar a decretação da intervenção provocada. Tipo 1 – Branca – Página 8"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',28,'Direito Administrativo',null,'Maria, procuradora-chefe do Município Alfa, foi consultada no corrente mês, pelo prefeito municipal, a respeito dos requisitos de ordem formal a serem observados caso se decidisse pela instituição de um regime próprio de previdência social em âmbito municipal. Maria respondeu, corretamente, que:','{"A": "é vedada a instituição de regime dessa natureza;", "B": "regime dessa natureza pode ser instituído por lei ordinária municipal, observada a simetria com o regime geral de previdência social;", "C": "regime dessa natureza só pode ser instituído pela lei orgânica municipal, observados os balizamentos estabelecidos em lei complementar nacional;", "D": "regime dessa natureza pode ser instituído por lei ordinária municipal, observados os balizamentos estabelecidos em lei complementar nacional;", "E": "regime dessa natureza só pode ser instituído por lei complementar municipal, observados os balizamentos estabelecidos em lei ordinária nacional."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',29,'Direito Administrativo',null,'Após um acordo entre as lideranças partidárias, 27 senadores requereram a criação de uma comissão parlamentar de inquérito (CPI) com o objetivo de apurar notícias de que determinados ilícitos estavam sendo praticados no âmbito de uma autarquia federal. Alguns dos subscritores do requerimento almejavam que a CPI, uma vez instalada, determinasse (1) a interceptação telefônica dos suspeitos da prática de ilícitos e (2) a quebra do seu sigilo bancário. À luz da sistemática constitucional, é correto afirmar que o número de assinaturas:','{"A": "impõe a criação da CPI, cuja instalação não pode ser obstada pela maioria parlamentar ou por órgão diretivo do Senado, sendo que apenas a medida alvitrada em 1 poderia ser adotada;", "B": "impõe a criação da CPI, cuja instalação não pode ser obstada pela maioria parlamentar ou por órgão diretivo do Senado, sendo que apenas a medida alvitrada em 2 poderia ser adotada;", "C": "é insuficiente para a criação da CPI, sendo que, caso uma CPI fosse criada e instalada, as medidas alvitradas em 1 e 2 poderiam ser adotadas;", "D": "é insuficiente para a criação da CPI, sendo que, caso uma CPI fosse criada e instalada, apenas a medida alvitrada em 2 poderia ser adotada;", "E": "é suficiente para o conhecimento do requerimento, mas a criação e consequente instalação da CPI dependem de deliberação da maioria, sendo que apenas a medida alvitrada em 2 poderia ser adotada."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',30,'Direito Administrativo',null,'O juízo de direito de primeira instância, em decisão confirmada pelo Tribunal de Justiça do Estado Alfa, proferiu decisão em que foi negada a legitimidade do Tribunal de Contas Estadual para executar as decisões que proferira, aplicando a sanção de multa aos ordenadores de despesa municipais que causaram danos ao erário municipal. À luz da sistemática vigente, esse entendimento se mostra:','{"A": "certo, pois a execução deveria ser promovida pelo Ministério Público de Contas;", "B": "certo, pois a execução deveria ser promovida pela Procuradoria do Estado;", "C": "errado, pois a multa consubstancia medida punitiva, que deve ser recolhida aos cofres do respectivo Tribunal de Contas;", "D": "errado, pois a multa consubstancia medida punitiva, que deve ser recolhida aos cofres do Estado, por iniciativa do Tribunal de Contas;", "E": "certo, pois a execução deveria ser promovida pela Procuradoria do Município a que está vinculado o respectivo ordenador."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',31,'Direito Constitucional',null,'O prefeito do Município Alfa consultou sua assessoria a respeito da possibilidade de ser majorado o valor venal dos imóveis, via decreto, sem a prévia aprovação de lei que autorizasse essa prática. A consulta do prefeito estava diretamente relacionada à conhecida defasagem do valor venal, o que vinha diminuindo a arrecadação do imposto sobre a propriedade predial e territorial urbana, e à forte mobilização da oposição no âmbito da Câmara Municipal, impedindo a aprovação de uma lei com esse objetivo. A assessoria respondeu, corretamente, que:','{"A": "a majoração do valor venal do imóvel, por estar dissociada do fato gerador do referido imposto, pode ser realizada via decreto;", "B": "qualquer majoração do valor venal do imóvel, ainda que adstrita à correção pelo índice inflacionário anual, exige lei em sentido formal;", "C": "a majoração do valor venal do imóvel, caso se mantenha adstrita à correção pelo índice inflacionário anual, independe de lei em sentido formal;", "D": "na ponderação entre os princípios envolvidos, deve preponderar o interesse público na arrecadação, o que autoriza a majoração do valor venal via decreto;", "E": "está ínsita na competência tributária a adoção dos meios necessários à sua efetivação, de modo que a majoração do valor do imposto, via decreto, decorre da sua criação. Tipo 1 – Branca – Página 9"}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',32,'Direito Constitucional',null,'O Estado Alfa editou norma, por meio de emenda à sua Constituição estadual, estabelecendo que o teto remuneratório dos servidores públicos do Estado e dos Municípios é o subsídio mensal dos desembargadores do Tribunal de Justiça. De acordo com a jurisprudência do Supremo Tribunal Federal, a citada norma:','{"A": "é inconstitucional, pois o teto aplicável aos servidores municipais é, em regra, o subsídio do prefeito;", "B": "é constitucional, pois se trata da aplicação do subteto facultativo único para todos os poderes do Estado e dos correlatos Municípios;", "C": "deve ser objeto de interpretação conforme a Constituição da República de 1988, de maneira que o mencionado teto remuneratório não se aplique aos subsídios dos membros dos poderes;", "D": "deve ser objeto de interpretação conforme a Constituição da República de 1988, de maneira que o mencionado teto remuneratório seja limitado a 95% do subsídio mensal dos ministros do Supremo Tribunal Federal;", "E": "é materialmente constitucional, por tratar do tema nos limites autorizados pela Constituição da República de 1988, mas formalmente inconstitucional, pois, em relação aos Municípios, seria necessária emenda às respectivas leis orgânicas."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',33,'Direito Constitucional',null,'O Município Gama deseja realizar a aquisição de imóvel, cujas características de instalações e de localização tornam necessária sua escolha. Assim sendo, o Município instaurou processo administrativo, no bojo do qual foi certificada a inexistência de imóveis públicos vagos e disponíveis que atendam ao objeto e foram apresentadas as justificativas que demonstram a singularidade do imóvel a ser comprado pela Administração e que evidenciam vantagem para ela. No caso em tela, de acordo com a nova Lei de Licitações e Contratos (Lei nº 14.133/2021), a aquisição ocorrerá mediante:','{"A": "dispensa de licitação, devendo haver prévias avaliação do bem, autorização legislativa e homologação da compra pelo Tribunal de Contas do Estado;", "B": "dispensa de licitação, devendo haver prévias avaliação do bem e autorização legislativa, assim como demonstração de que o valor a ser gasto está compatível com o valor de mercado;", "C": "dispensa de licitação, devendo haver prévias avaliação do bem e autorização do Tribunal de Contas do Estado, assim como demonstração de que o valor a ser gasto está compatível com o valor de mercado;", "D": "inexigibilidade de licitação, devendo haver prévias avaliação do bem e autorização legislativa, assim como demonstração de que o valor a ser gasto está compatível com o valor de mercado;", "E": "inexigibilidade de licitação, devendo haver avaliação prévia do bem, do seu estado de conservação, dos custos de adaptações, quando imprescindíveis às necessidades de utilização, e do prazo de amortização dos investimentos."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',34,'Direito Constitucional',null,'O Tribunal de Contas do Estado Beta aplicou ao prefeito João, do Município Alfa, multa em razão de danos causados ao erário municipal. A decisão do Tribunal de Contas já transitou em julgado, mas João não pagou a multa. Consoante atual jurisprudência do Supremo Tribunal Federal, no caso em tela, quem tem legitimidade para executar o crédito decorrente da multa aplicada a João é o:','{"A": "Estado Beta.", "B": "Município Alfa;", "C": "Tribunal de Contas do Estado Beta, por meio de sua Procuradoria-Geral;", "D": "Tribunal de Contas do Estado Beta, por meio do Ministério Público de Contas;", "E": "Tribunal de Contas do Estado Beta, por meio do conselheiro relator do processo de onde se originou a aplicação da multa."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',35,'Direito Constitucional',null,'José, prefeito do Município Delta, de forma dolosa, praticou ação que ensejou, efetiva e comprovadamente, perda patrimonial do Município, na medida em que, consciente e voluntariamente, realizou operação financeira sem observância das normas legais, causando dano ao erário. Consoante dispõe a Lei de Improbidade Administrativa, com redação atual dada pela Lei nº 14.230/2021, em tese, José:','{"A": "não praticou ato de improbidade administrativa, por falta de adequação típica, mas é passível de responsabilização pelo Tribunal de Contas estadual;", "B": "não praticou ato de improbidade administrativa, por revogação do tipo anterior que considerava a conduta praticada como ato ímprobo, mas pode lhe ser imputado crime de responsabilidade;", "C": "praticou ato de improbidade administrativa e é inviável qualquer tipo de transação, diante da indisponibilidade do direito sancionador, de maneira que José está sujeito, entre outras sanções, à perda da função pública e suspensão dos direitos políticos;", "D": "praticou ato de improbidade administrativa e, caso preenchidos os requisitos legais, é possível a celebração de termo de ajustamento de conduta com o Tribunal de Contas, ouvido o Ministério Público que se manifestará acerca do valor do dano ao erário, com indicação dos parâmetros utilizados, no prazo de trinta dias;", "E": "praticou ato de improbidade administrativa e, caso preenchidos os requisitos legais, é possível a celebração de acordo de não persecução cível com o Ministério Público, circunstância em que, para fins de apuração do valor do dano a ser ressarcido, deve ser realizada a oitiva do Tribunal de Contas, que se manifestará, com indicação dos parâmetros utilizados, no prazo de noventa dias. Tipo 1 – Branca – Página 10"}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',36,'Direito Constitucional',null,'O Tribunal de Contas do Estado do Tocantins, ao apreciar os processos, decidirá: I. em relação ao julgamento das contas públicas, pela regularidade, regularidade com ressalva, irregularidade, ou no sentido de serem as contas iliquidáveis; II. em relação aos processos de admissão, aposentadorias, reformas e pensões, pelo registro ou não do ato e legalidade ou ilegalidade da despesa; III. no caso de parecer prévio, pela aprovação ou rejeição das contas anuais. De acordo com a Lei Orgânica do Tribunal de Contas do Estado do Tocantins, está correto o que se afirma em:','{"A": "somente II;", "B": "somente III;", "C": "somente I e III;", "D": "somente II e III;", "E": "I, II e III."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',37,'Direito Constitucional',null,'As autoridades públicas devem atuar para aumentar a segurança jurídica na aplicação das normas, inclusive por meio de regulamentos, súmulas administrativas e respostas a consultas. Nesse sentido, a Lei de Introdução às Normas do Direito Brasileiro (Decreto-Lei nº 4.657/1942, com redação dada pela Lei nº 13.655/2018) dispõe que, em qualquer órgão ou Poder, a edição de atos normativos por autoridade administrativa, salvo os de mera organização interna:','{"A": "poderá ser precedida de consulta pública para manifestação de interessados, exclusivamente por meio eletrônico e pelo prazo mínimo de trinta dias, caso haja recomendação do órgão de controle interno;", "B": "deverá ser precedida de consulta pública para manifestação de interessados, caso haja recomendação do órgão de controle externo, sob pena de nulidade do ato normativo, por abuso de poder, na modalidade desvio de competência;", "C": "deverá ser precedida de consulta pública para manifestação de interessados, para o exercício regular e legítimo do poder administrativo disciplinar, que embasa diretamente a edição de atos normativos;", "D": "poderá ser precedida de consulta pública para manifestação de interessados, e a convocação conterá a minuta do ato normativo e fixará o prazo e demais condições da consulta pública, observadas as normas legais e regulamentares específicas, se houver;", "E": "deverá ser precedida de consulta pública para manifestação de interessados, caso haja recomendação do órgão de controle externo, sob pena de nulidade do ato normativo, por abuso de poder, na modalidade desvio de finalidade."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',38,'Direito Constitucional',null,'Lei estadual de iniciativa do governador do Estado criou a nova Secretaria Estadual de Combate a Calamidades Públicas. Contudo, não havia ainda dotação na lei orçamentária anual (LOA) para atender às novas despesas necessárias ao funcionamento do novo órgão estadual ainda dentro daquele ano, sem necessidade de se aguardar a elaboração da LOA do ano seguinte. Diante desse cenário, foi necessária a autorização da abertura de créditos por lei para cumprimento dessa finalidade, com devida indicação dos recursos correspondentes. À luz da Lei nº 4.320/1964, tais créditos cuja abertura foi autorizada classificam-se como:','{"A": "ordinários;", "B": "especiais;", "C": "suplementares;", "D": "extraordinários;", "E": "por antecipação de receita."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',39,'Direito Constitucional',null,'A Procuradoria-Geral e a Secretaria da Fazenda do Estado Beta, após os devidos estudos, chegaram à conclusão de que o custo de cobrança de alguns créditos inscritos em dívida ativa estadual suplantavam bastante o valor dos próprios créditos a serem cobrados. Por isso, encaminharam ao governador a orientação de que houvesse o cancelamento de tais débitos cujo montante fosse inferior ao dos respectivos custos de cobrança. Diante desse cenário, à luz do princípio da eficiência e da Lei de Responsabilidade Fiscal, tal cancelamento:','{"A": "deverá estar acompanhado de medidas de compensação, por meio do aumento de receita, proveniente da elevação de alíquotas, ampliação da base de cálculo, majoração ou criação de tributo ou contribuição;", "B": "deverá estar acompanhado de demonstração de que não afetará as metas de resultados fiscais previstas no anexo próprio da lei de diretrizes orçamentárias;", "C": "deverá estar acompanhado de estimativa do impacto orçamentário-financeiro no exercício em que deva iniciar sua vigência e nos dois seguintes;", "D": "entrará em vigor apenas quando implementadas medidas de compensação;", "E": "não se classifica como renúncia de receita pública para fins da Lei de Responsabilidade Fiscal. Tipo 1 – Branca – Página 11"}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',40,'Direito Financeiro',null,'Em 2022, último ano de mandato do governador do Estado Gama, apurou-se que, no primeiro quadrimestre, a despesa total com pessoal do Poder Executivo estadual alcançou o percentual de 49,5% da receita corrente líquida (RCL). Diante dessa apuração feita ao final do primeiro quadrimestre de 2022 e à luz da Lei de Responsabilidade Fiscal, analise as afirmativas a seguir. I. O Poder Executivo fica impedido de obter garantia, direta ou indireta, de outro ente. II. O Poder Executivo fica impedido de receber transferências obrigatórias. III. Os Poderes do Estado Gama ficam impedidos de alterar a estrutura de carreira dos servidores que implique aumento de despesa. Está correto o que se afirma em:','{"A": "somente I;", "B": "somente II;", "C": "somente III;", "D": "somente II e III;", "E": "I, II e III."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',41,'Direito Financeiro',null,'O presidente da República enviou ao Congresso Nacional o projeto de lei de diretrizes orçamentárias (LDO) para o ano de 2022. No Legislativo, o projeto começou a tramitar na Comissão Mista permanente de Planos, Orçamentos Públicos e Fiscalização (CMO). Enquanto seguiam os trabalhos de exame na CMO, o presidente da República enviou mensagem ao Congresso Nacional para propor alteração em uma parte do projeto da LDO. Diante desse cenário e à luz da Constituição da República de 1988, é correto afirmar que:','{"A": "uma vez encaminhado o projeto de LDO ao Congresso Nacional, o presidente da República não poderá mais enviar mensagem ao Legislativo para propor modificações a esse projeto;", "B": "a CMO é composta por deputados, senadores, membros representantes da sociedade civil escolhidos pelo Congresso Nacional, membros da Secretaria do Tesouro Nacional e membros indicados pelo Tribunal de Contas da União;", "C": "a emissão de parecer da CMO sobre o projeto de LDO, devidamente votado e aprovado no âmbito dessa Comissão Mista, dispensa a votação posterior pelos demais membros da Câmara dos Deputados e do Senado Federal;", "D": "deve integrar o projeto de LDO, para o exercício de 2022 e, pelo menos, para os dois exercícios subsequentes, anexo com previsão de agregados fiscais e a proporção dos recursos para investimentos que serão alocados na lei orçamentária anual para a continuidade daqueles em andamento;", "E": "diferentemente do projeto de lei orçamentária anual, em que podem ser propostas emendas parlamentares ao projeto, não se admite a apresentação na CMO de emendas parlamentares ao projeto de LDO."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',42,'Direito Financeiro',null,'O Município X requereu ao BNDES (instituição financeira federal) a concessão de empréstimo, em regime de juros especiais para os entes municipais, a fim de obter recursos para pagamento de aumento concedido aos servidores municipais ativos. Diante desse cenário e à luz da Constituição da República de 1988, esse empréstimo requerido pelo Município X junto ao BNDES:','{"A": "pode ser realizado, uma vez que será feito em regime de juros especiais para os entes municipais;", "B": "pode ser realizado, uma vez que é permitido junto a instituição financeira vinculada ao governo federal;", "C": "não pode ser realizado, uma vez que é vedado junto a instituição financeira vinculada ao governo federal;", "D": "não pode ser realizado, uma vez que é permitido apenas junto a instituição financeira vinculada ao governo estadual;", "E": "não pode ser realizado, uma vez que é permitido apenas para pagamento de proventos de aposentadoria de servidores inativos e seus respectivos pensionistas."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',43,'Direito Tributário',null,'Analise as situações apresentadas a seguir e, à luz da Lei nº 4.320/1964, classifique as seguintes despesas públicas abaixo relacionadas. I. Pagamento de pensionistas de militares falecidos do Corpo de Bombeiros Estadual; II. Amortização da dívida pública estadual; III. Aquisição de galpão onde já funciona posto do Detran. A classificação correta é, respectivamente:','{"A": "I. Despesa de custeio; II. Transferência corrente; III. Investimento;", "B": "I. Despesa de custeio; II. Transferência de capital; III. Inversão financeira;", "C": "I. Despesa de custeio; II. Transferência de capital; III. Investimento;", "D": "I. Transferência corrente; II. Transferência corrente; III. Investimento;", "E": "I. Transferência corrente; II. Transferência de capital; III. Inversão financeira."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',44,'Direito Tributário',null,'Marcos, proprietário de três imóveis em Palmas/TO e domiciliado nesse Município, resolve em 2021 fazer doação de um dos imóveis a seu único herdeiro, seu filho João, domiciliado em Fortaleza/CE. A doação é devidamente registrada no Registro de Imóveis, mas com subavaliação do bem, resultando em pagamento a menor do Imposto sobre a transmissão causa mortis e doação (ITCMD), o que somente é percebido posteriormente pelo Fisco estadual. Diante desse cenário e à luz do Código Tributário do Estado do Tocantins, é correto afirmar que:','{"A": "João é o contribuinte do ITCMD incidente sobre esta doação;", "B": "Marcos é o contribuinte do ITCMD incidente sobre esta doação;", "C": "o Fisco estadual poderá fazer um lançamento por declaração da parte que não foi recolhida;", "D": "o Fisco estadual poderá fazer um lançamento por homologação da parte que não foi recolhida;", "E": "na impossibilidade de exigência do cumprimento da parcela faltante da obrigação principal pelo contribuinte João, Marcos responderá solidariamente com ele. Tipo 1 – Branca – Página 12"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',45,'Direito Tributário',null,'Maria, domiciliada em Porto Nacional/TO, pagou em cota única, em janeiro de 2021, o Imposto sobre a Propriedade de Veículos Automotores (IPVA) de seu automóvel licenciado e emplacado nesse Município. Não percebera, porém, que não havia pagado o débito de IPVA referente ao ano de 2014. Em 01/06/2021, teve seu automóvel furtado. Dirigiu-se até uma delegacia de polícia para registrar a ocorrência policial, tendo havido também comunicação pelo sistema Renavam ao Detran/TO. Diante desse cenário e à luz do Código Tributário do Estado do Tocantins, é correto afirmar que:','{"A": "o IPVA não poderá ter alíquotas diferenciadas em função do tipo e utilização do automóvel;", "B": "a dívida de IPVA referente ao ano de 2014 foi alcançada pela decadência tributária;", "C": "ao Município de Porto Nacional pertence 75% do produto da arrecadação do IPVA dos automóveis licenciados em seu território;", "D": "cabe pedido de restituição do IPVA pago proporcionalmente, à razão de 1/12 por mês, contado a partir do mês seguinte à data do evento, desde que haja o prévio reconhecimento da isenção pela Secretaria da Fazenda;", "E": "havendo valores a débito e a crédito de IPVA, incidentes sobre um mesmo veículo, a Secretaria da Fazenda somente pode processar a compensação destes se houver expressa solicitação do contribuinte."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',46,'Direito Tributário',null,'A sociedade empresária XYZ Ltda. possuía débitos de taxas estaduais e resolveu aderir a um programa de parcelamento de débitos tributários inscritos em dívida ativa previsto em lei específica do Estado Alfa. Diante desse cenário e à luz do Código Tributário Nacional, é correto afirmar que:','{"A": "o momento da concessão de tal parcelamento é causa de extinção do crédito tributário;", "B": "XYZ Ltda. fará jus a uma certidão positiva com efeitos de negativa durante a pendência de tal parcelamento;", "C": "a dívida ativa regularmente inscrita goza da presunção de certeza e liquidez, mas sem efeito de prova pré-constituída;", "D": "não podem ser aplicadas subsidiariamente ao parcelamento as disposições relativas à moratória previstas no Código Tributário Nacional;", "E": "durante tal parcelamento, fica suspenso o cumprimento das obrigações acessórias dependentes da obrigação principal cujo crédito está sendo parcelado."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',47,'Direito Tributário',null,'Quanto às imunidades constitucionais de tributos relacionados ao prédio-sede do Tribunal de Contas do Estado Beta, de propriedade do mesmo Estado, analise as afirmativas a seguir. I. Há imunidade quanto à contribuição municipal para o custeio dos serviços de iluminação pública incidente sobre o consumo de energia deste prédio-sede de Tribunal de Contas Estadual. II. Não há imunidade quanto à taxa municipal de coleta de lixo domiciliar proveniente deste prédio-sede de Tribunal de Contas Estadual. III. Há imunidade quanto à contribuição de melhoria municipal instituída para fazer face ao custo de obras públicas de que decorra valorização imobiliária deste prédio-sede de Tribunal de Contas Estadual. Está correto o que se afirma em:','{"A": "somente I;", "B": "somente II;", "C": "somente III;", "D": "somente I e III;", "E": "I, II e III."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',48,'Direito Tributário',null,'O presidente da República, por meio de decreto publicado no Diário Oficial da União em janeiro de 2022, visando a estimular o consumo, reduziu para zero a alíquota do Imposto sobre Produtos Industrializados (IPI) referente a certos produtos eletrodomésticos, a contar da data de sua publicação. Diante desse cenário, o referido decreto:','{"A": "não poderia reduzir a zero tal alíquota;", "B": "violou o princípio da legalidade tributária;", "C": "poderia elevar a alíquota do IPI, mas não reduzi-la;", "D": "não violou o princípio da anterioridade tributária nonagesimal;", "E": "violou o princípio da anterioridade tributária do exercício financeiro seguinte."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',49,'Direito Civil',null,'Zelinda e Cláudio compareceram ao cartório para celebrar contrato de compra e venda de imóvel, tendo declarado, para fins de lavratura da escritura pública, que o preço pago por Zelinda seria de R$ 1.200.000,00 em troca da transferência da propriedade do apartamento de Cláudio. Entretanto, o que seria efetivamente pago, conforme avençado entre os dois, era o valor de R$ 2.000.000,00, que foi o montante efetivamente recebido por Cláudio de Zelinda: o acordo entre as partes para a declaração de valor menor tinha por objetivo pagar menos impostos. Nesse caso, ocorreu:','{"A": "fraude contra credores;", "B": "dolo;", "C": "lesão;", "D": "simulação;", "E": "estado de perigo. Tipo 1 – Branca – Página 13"}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',50,'Direito Empresarial',null,'Fabiano, portador de nota promissória vencida há três meses, e sem receber o devido pagamento, realizou, junto ao tabelionato competente, o protesto desse título de crédito. Diante disso, o protesto cambial:','{"A": "interrompe o prazo prescricional;", "B": "suspende o prazo prescricional;", "C": "impede a fluência do prazo prescricional;", "D": "prorroga o prazo prescricional;", "E": "não influi no prazo prescricional."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',51,'Direito Empresarial',null,'A JPD está sendo cobrada por uma multa contratual de dez mil reais em virtude de não ter cumprido pontualmente sua obrigação de fornecer à LMT determinado maquinário. A cobrança é objeto de litígio judicial, pois a JPD alega que a multa é excessiva, enquanto a LMT, ao contrário, reputa o valor insuficiente para cobrir seus prejuízos e requer majoração. Sobre o caso, é correto afirmar que:','{"A": "a redução equitativa da multa pode ser realizada de ofício pelo juiz, se reputá-la manifestamente excessiva, tendo em vista a natureza e a finalidade da obrigação;", "B": "não será possível a redução judicial da multa se houver cláusula expressa afastando essa possibilidade, tendo em vista se tratar de contrato paritário;", "C": "caso comprovado que a multa não é suficiente para cobrir o prejuízo da LMT, será cabível indenização suplementar, salvo cláusula em sentido contrário;", "D": "o juiz poderá reduzir a multa a zero, afastando sua cominação, se o credor não for capaz de provar ter sofrido qualquer prejuízo em decorrência do inadimplemento;", "E": "o valor da multa somente poderá ser reduzido em caso de cumprimento parcial da obrigação que ela garante."}'::jsonb,'A',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',52,'Direito Empresarial',null,'Quando a Gama S/A, firma de contabilidade, decidiu fechar seu escritório no centro de Palmas, optou por vender as três impressoras seminovas que lá se encontravam. A Grafet Ltda. comprou as três, mas constatou problemas após recebê-las. O rolamento interno da impressora X estava desgastado pelo uso, embora isso não chegasse a prejudicar a impressão ou o seu valor. A bandeja externa de papel da impressora Y estava quebrada e não encaixava mais na máquina, tanto que foi recebida em separado. A impressora Z, por sua vez, funcionou bem durante uma semana, mas depois parou: o técnico chamado informou que a causa do defeito foi um cabeçote interno, que deveria ter sido substituído há pelo menos seis meses. Diante disso, a Grafet pode enjeitar, por vício redibitório:','{"A": "a impressora X;", "B": "as impressoras X e Y;", "C": "a impressora Y;", "D": "as impressoras Y e Z;", "E": "a impressora Z."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',53,'Direito Civil',null,'Marcelo adquiriu há mais de três anos uma casa de veraneio no campo. Entretanto, nunca ocupou ou exerceu quaisquer atos de posse sobre o bem. Até o momento, todavia, ninguém mais veio a apossar-se do bem, estando ainda desocupado. Caso a conduta de Marcelo venha a ser considerada abandono do bem, ele poderá ser arrecadado pelo(a):','{"A": "União, caso se trate de imóvel urbano, onde quer que ele se localize;", "B": "Estado, caso se trate de imóvel urbano e se encontre na respectiva circunscrição;", "C": "Município ou Distrito Federal, caso se trate de imóvel urbano e se encontre na respectiva circunscrição;", "D": "Estado, caso se trate de imóvel rural e se encontre na respectiva circunscrição;", "E": "Município ou Distrito Federal, caso se trate de imóvel rural e se encontre na respectiva circunscrição."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',54,'Direito Civil',null,'Astolfo e Maria casaram-se sob o regime da comunhão parcial de bens. Na constância do casamento, Astolfo ganhou um barco em um sorteio no clube e recebeu um sítio de presente de seu pai; Maria recebeu um apartamento por herança de sua mãe e comprou uma casa. Na hipótese de divórcio, serão considerados bens comuns somente:','{"A": "a casa;", "B": "o apartamento;", "C": "o barco e o sítio;", "D": "o barco e a casa;", "E": "o sítio, o apartamento e a casa."}'::jsonb,'D',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',55,'Direito Penal',null,'No tocante à extinção da punibilidade penal, é correto afirmar que:','{"A": "no crime de peculato culposo, a reparação do dano, se realizada após a sentença irrecorrível, acarreta a extinção da punibilidade;", "B": "nos crimes conexos, a extinção da punibilidade de um deles não impede, quanto aos outros, a agravação da pena resultante da conexão;", "C": "no crime de apropriação indébita previdenciária, extingue-se a punibilidade com o pagamento das contribuições devidas à previdência social, se realizado após o início da ação fiscal;", "D": "nos crimes contra a administração pública, estende-se o perdão judicial aos demais participantes do crime, em razão de se tratar de circunstância pessoal;", "E": "nos crimes contra a ordem tributária, o pagamento integral do tributo, após a sentença condenatória irrecorrível, implica extinção da punibilidade. Tipo 1 – Branca – Página 14"}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',56,'Direito Penal',null,'A prefeita Rebeca, juntamente com a secretária municipal Raquel, em perfeita comunhão de ações e desígnios, com vistas a direcionarem determinado procedimento licitatório à empresa de Renato, empresário e parente em comum de ambas, ofereceram vantagem econômica consistente em R$ 50.000,00 à licitante e empresária Sofia para que esta desistisse da licitação. Sofia desistiu em razão de ter aceitado o referido valor, sendo o certame licitatório vencido pela empresa de Renato. Sob o prisma penal, é correto afirmar, em relação às condutas de Rebeca, Raquel e Sofia, que:','{"A": "Rebeca e Raquel cometeram o crime de corrupção ativa, e Sofia, o de corrupção passiva;", "B": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e Sofia, o de corrupção ativa;", "C": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e a conduta de Sofia é penalmente atípica;", "D": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e Sofia, o de corrupção passiva;", "E": "Rebeca e Raquel cometeram o crime de afastamento de licitante, e Sofia incorre nas mesmas penas do crime de afastamento de licitante."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',57,'Direito Penal',null,'Em relação à prescrição como causa de extinção da punibilidade, é correto afirmar que:','{"A": "os prazos prescricionais previstos para as penas privativas de liberdade não se aplicam às penas restritivas de direito;", "B": "o prazo prescricional começa a correr, antes de a sentença transitar em julgado, nos crimes permanentes, do dia em que cessou a permanência;", "C": "os prazos prescricionais se reduzem de 1/3 se o criminoso era, ao tempo do crime, maior de 70 anos;", "D": "o curso do prazo prescricional se interrompe pelo oferecimento da denúncia;", "E": "a prescrição da pena de multa ocorrerá em três anos quando a multa for a única pena cominada ou aplicada."}'::jsonb,'B',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',58,'Direito Penal',null,'A respeito das normas e princípios que regem a aplicação da lei penal no tempo e no espaço, é correto afirmar que:','{"A": "admite-se sejam as normas penais incriminadoras criadas por lei, medida provisória ou decreto legislativo;", "B": "considera-se praticado o crime no momento de seu resultado, ainda que outro seja o momento da ação ou omissão;", "C": "aplica-se a lei penal incriminadora mais gravosa a fatos anteriores já decididos por sentença condenatória transitada em julgado;", "D": "aplicam-se as regras gerais do Código Penal aos crimes previstos em lei especial, se esta dispuser de maneira diversa;", "E": "aplica-se a lei penal temporária, embora decorrido o período de sua duração, aos fatos praticados durante a sua vigência."}'::jsonb,'E',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',59,'Direito Penal',null,'Renato, Ricardo e Roberto, policiais civis lotados na Secretaria Municipal de Segurança Pública de determinado Município, associaram-se, entre si, com perfeita divisão de tarefas, para a prática de vários crimes de extorsão, de concussão e de corrupção, utilizando-se, para a prática de alguns delitos, das armas de fogo que possuíam em razão de suas funções. Os três foram presos em flagrante quando do cometimento de um delito de corrupção, para a consecução do qual não se utilizaram das referidas armas de fogo. Além de responderem pelo crime de corrupção, o fato de terem se associado para a prática de crimes corresponde à figura típica de crime de:','{"A": "associação criminosa, com a incidência da majorante relativa ao fato de os agentes serem servidores públicos;", "B": "constituição de milícia privada, não incidindo a majorante do emprego de arma de fogo;", "C": "associação criminosa, com incidência da causa de aumento de pena em razão de a associação ser armada;", "D": "constituir e integrar organização criminosa armada, não incidindo a majorante do emprego de arma de fogo;", "E": "constituir e integrar organização criminosa armada, com incidência da majorante pelo fato de os agentes serem servidores públicos."}'::jsonb,'C',true,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',60,'Direito Penal',null,'Relativamente às condutas que caracterizam o crime de lavagem de dinheiro previsto na Lei nº 9.613/1998, é correto afirmar que:','{"A": "a infração penal antecedente deve ser crime punido com reclusão e gerar proveito econômico àquele que pratica o crime de lavagem;", "B": "não se punem as formas tentadas das condutas que consubstanciam o crime de lavagem de dinheiro;", "C": "a pena será aumentada de 1/3 a 2/3 se o crime for cometido por intermédio de organização criminosa;", "D": "não se pune a dissimulação de valores provenientes de infração penal quando são convertidos em ativos lícitos;", "E": "extinta a punibilidade da infração penal antecedente, deixa de ser punível o crime de lavagem de dinheiro."}'::jsonb,'C',false,true,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',61,'Administração Financeira e Orçamentária',null,'O modelo orçamentário de referência para o planejamento das entidades públicas brasileiras é o orçamento-programa. A classificação programática da despesa está alinhada a esse modelo. Nesse contexto, um instrumento de programação que envolve um conjunto de operações que se realizam de modo contínuo e permanente e que contribuem para a manutenção da ação de governo, a exemplo de fiscalização e monitoramento da qualidade de combustíveis automotores, deve ser classificado como:','{"A": "aplicação direta;", "B": "atividade;", "C": "projeto;", "D": "operação especial;", "E": "encargo especial. Tipo 1 – Branca – Página 15"}'::jsonb,'B',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',62,'Administração Financeira e Orçamentária',null,'Um estado da federação recebeu recursos decorrentes de emendas individuais impositivas apresentadas ao projeto de Lei Orçamentária Anual da União, por meio de transferência especial. Os recursos foram da ordem de R$ 800 mil. Pelas regras constitucionais, para aplicação desses recursos:','{"A": "até R$ 200 mil poderão ser aplicados em despesas com ações e serviços públicos de saúde;", "B": "até R$ 200 mil poderão ser aplicados na amortização da dívida consolidada do ente;", "C": "o valor deverá ser igualmente dividido entre despesas e ações nas áreas de saúde e de educação;", "D": "o valor total deverá ser aplicado nas áreas de competência constitucional da União;", "E": "pelo menos R$ 560 mil deverão ser aplicados em despesas de capital."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',63,'Administração Financeira e Orçamentária',null,'Em sentido amplo, os ingressos de recursos financeiros nos cofres do Estado denominam-se receitas públicas, porém nem todas pertencem efetivamente ao ente e são destinadas ao custeio da ação pública. Esse é o caso de receitas:','{"A": "decorrentes de juros de operações de crédito;", "B": "geradas pela alienação de bens do patrimônio público;", "C": "originárias de compensações financeiras;", "D": "que representam apenas entradas compensatórias;", "E": "que resultam da cobrança de dívida ativa."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',64,'Administração Financeira e Orçamentária',null,'Com o intuito de subsidiar a promoção de uma gestão fiscal responsável, a Lei de Responsabilidade Fiscal dispôs sobre a definição de metas e restrições para assegurar o cumprimento dessas metas. A limitação de empenho e movimentação financeira é uma medida que deve ser adotada quando a realização da receita ameaçar o cumprimento das metas de resultado primário ou nominal, e pode incidir sobre despesas:','{"A": "com juros e encargos da dívida;", "B": "com pagamento de pessoal e encargos sociais;", "C": "de transferências intergovernamentais legalmente previstas;", "D": "discricionárias destinadas a ações e serviços públicos de saúde;", "E": "relativas à inovação custeadas por fundo criado para tal finalidade."}'::jsonb,'D',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',65,'Administração Financeira e Orçamentária',null,'Ao final de um determinado período de apuração, um estado da federação apurou uma Receita Corrente Líquida de R$ 12 bilhões. A partir das disposições da Lei de Responsabilidade Fiscal, o percentual de despesa total com pessoal do tribunal de contas do referido ente:','{"A": "deve se limitar a 2,5% da RCL;", "B": "está limitado a 2% da RCL;", "C": "corresponde a 0,6% da RCL;", "D": "é apurado de forma consolidada com o Poder Executivo;", "E": "é definido juntamente com o do Poder Legislativo."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',66,'Auditoria',null,'As normas de auditoria exigem que o trabalho do auditor seja adequadamente planejado. Um dos objetivos principais do planejamento da auditoria é auxiliar o auditor:','{"A": "quanto a forma e conteúdo de sua opinião no relatório de auditoria das demonstrações contábeis;", "B": "a uma efetiva comunicação com os responsáveis pela governança e identificar alguns assuntos específicos a serem comunicados a eles;", "C": "a avaliar o efeito de distorções identificadas durante a auditoria;", "D": "a avaliar o efeito de distorções não corrigidas nas demonstrações contábeis;", "E": "a conhecer a natureza das operações e dos negócios da organização para definir o alcance, a época e a direção da auditoria."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',67,'Auditoria',null,'A metodologia de avaliação dos controles internos consiste em avaliar os controles internos existentes e quantificá-los em níveis de efetividade. Dessa forma, uma empresa apresentou os seguintes controles internos, avaliados em: 1 (controles não funcionais), 0,5 (controles funcionais medianos) e 0,2 (controles funcionais fortes). Os auditores, ao solicitarem tais documentos de avaliação, podem concluir que:','{"A": "caso existam controles funcionais em uma atividade, a multiplicação do risco residual ao valor do nível dos controles internos resultará em um menor risco inerente;", "B": "independentemente do nível de controles internos, a multiplicação do risco inerente ao valor do nível dos controles internos resultará em um maior risco residual;", "C": "caso existam controles funcionais em uma atividade, a multiplicação do risco inerente ao valor do nível dos controles internos resultará em um menor risco residual;", "D": "independentemente do nível de controles internos, a multiplicação do risco inerente ao valor do nível dos controles internos resultará em um menor risco residual;", "E": "caso existam controles funcionais em uma atividade, a multiplicação da probabilidade e do impacto resultará em um menor risco residual."}'::jsonb,'C',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',68,'Auditoria',null,'O objetivo do auditor é definir e executar procedimentos de auditoria que permitam a ele conseguir evidência de auditoria apropriada e suficiente que lhe possibilite obter conclusões razoáveis para fundamentar a sua opinião. Nesse sentido, a confiabilidade da evidência de auditoria é influenciada pela fonte, por sua natureza e é mais confiável quando obtida:','{"A": "de fontes independentes externas à entidade e confirmada em documento eletrônico ou em papel;", "B": "por meio da indagação a respeito da aplicação de controle, em vez da observação da aplicação de controle;", "C": "pela representação formal, pois fornece evidência de auditoria apropriada e suficiente;", "D": "pela cópia de um documento fiscal obtida por intermédio de fontes internas da empresa do que diretamente pelo auditor;", "E": "por meio da indagação a respeito da contagem de estoques, em vez da observação do auditor da contagem do estoque pelo pessoal da entidade. Tipo 1 – Branca – Página 16"}'::jsonb,'A',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',69,'Auditoria',null,'Uma empresa reapresentou valores em decorrência da adoção de novos pronunciamentos contábeis e o auditor emitiu em seu relatório de auditoria as seguintes informações: “Em nossa opinião, as demonstrações financeiras apresentam adequadamente, em todos os aspectos relevantes, a posição patrimonial e financeira, individual e consolidada, da empresa XYZ em 31 de dezembro de 20XX, o desempenho individual e consolidado de suas operações e os seus respectivos fluxos de caixa individuais e consolidados para o exercício findo nessa data, de acordo com as práticas contábeis adotadas no Brasil e com as normas internacionais de relatório financeiro. Conforme mencionado na nota explicativa X, em decorrência da adoção dos novos pronunciamentos contábeis, os valores correspondentes, individuais e consolidados, relativos aos balanços patrimoniais em 31 de dezembro de 20XX e as respectivas demonstrações do resultado, do resultado abrangente, das mutações do patrimônio líquido, dos fluxos de caixa e do valor adicionado para o exercício findo nessa data, apresentados para fins de comparação, foram ajustados e estão sendo reapresentados”. Dessa forma, o auditor emitiu uma opinião:','{"A": "com ressalva;", "B": "negativa;", "C": "modificada;", "D": "adversa;", "E": "com parágrafo de ênfase."}'::jsonb,'E',false,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Tribunal de Contas do Estado do Tocantins','Auditor de Controle Externo – Direito',2022,null,'Tipo 1',70,'Auditoria',null,'Existem diversos tipos de auditoria, contudo, uma delas possui características próprias que a distingue dos outros tipos. Dessa forma, a que apresenta uma variedade e complexidade de questões a serem tratadas, possui maior flexibilidade na escolha de temas, objetos de auditoria, métodos de trabalho e forma de comunicar suas conclusões é a auditoria:','{"A": "de conformidade;", "B": "financeira;", "C": "contábil;", "D": "operacional;", "E": "ambiental. DISCURSIVA 1 João Felipe teve seu registro de candidatura ao cargo de deputado estadual impugnado pela coligação “Justiça Agora!”, com o argumento de que o Tribunal de Contas do Estado do Tocantins, em sessão de outubro de 2021, emitiu parecer pela rejeição de suas contas referentes ao exercício do ano de 2020, quando ocupava o cargo de prefeito do Município de Gurupi/TO. Tendo em vista essa situação, discorra, de forma fundamentada, sobre: a) a natureza jurídica do parecer do Tribunal de Contas, à luz das suas atribuições; b) a natureza jurídica das contas do prefeito; c) a competência para apreciar as contas de prefeito. Valor: 15 pontos Máximo de 15 linhas. 2 Considere que você, como auditor do Tribunal de Contas do Estado Alfa, é integrante do setor responsável pelo controle da regularidade dos pagamentos de precatórios. Diante disso e apenas à luz da Constituição da República de 1988, apresente resumidamente as três ordens cronológicas de preferências no pagamento de precatórios e suas características essenciais, iniciando sua resposta com os créditos de precatórios que possuem maior prioridade até chegar àqueles com menor prioridade (não é necessário expor o trâmite para expedição dos precatórios). Valor: 15 pontos Máximo de 15 linhas. Tipo 1 – Branca – Página 17 RASCUNHO - Prova Discursiva - Questão 1 1 5 10 15 RASCUNHO - Prova Discursiva - Questão 2 1 5 10 15"}'::jsonb,'D',true,false,'TO','Tribunal de Contas','https://conhecimento.fgv.br/sites/default/files/concursos/auditor_de_controle_externo_-_direitoauddireito_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/tceto2022_gabarito_definitivo_164151578464.pdf','alternativa muito longa: pode conter texto de outra questão; depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno')
